[race_ed_phy]=[[
]],
[race_ed_btl]=[[
石巨人在戰鬥中儘可能與敵人保持距離，但是如果無法避免肉搏的話，他們會使用石頭鑿成的巨大棍棒戰鬥。

石巨人最喜愛的戰術是靜止不動的站著，融入周圍的環境中，然後再突然上前投擲石頭來突襲敵人。
]],
