s_gnt_se="石巨人長老"
s_gnt_se_var_n="迴歸的石巨人"
s_gnt_se_var_d="作為發展出特殊能力的石巨人，石巨人長老擁有石巨人的所有特性，除了以下不同："
s_gnt_se_fav_cls="石巨人長老擁有特殊能力以及較高的魅力值，很適合術士職業。"
s_gnt_se_traits=[[
<b c=tg>+16力量，+4敏捷，+8體質，+2感知，+6魅力：</b>與普通石巨人相比，石巨人長老更具有奧術天賦。

<b>類法術能力：</b>可施展<t=@pwr_sp_xxx c=fc_b>塑石術</t>、<t=@pwr_sp_xxx c=fc_b>石言術</t>、<t=@pwr_sp_xxx c=fc_b>化石為泥或化泥為石</t>，每天各一次，豁免難度等級基於魅力調整值，施法者等級等同角色等級。{hr_splk}
]]-- 一些石巨人可以發展出一些與其環境相關的特殊能力。這些石巨人長老的魅力值至少有15而且還能如等級10的術士一樣施展其類法術能力。每天一次他們可以使用塑石術，石言術，以及化石為泥或化泥為石 (DC 17)。豁免檢定DC基於魅力調整值。每10名長老中會有1名術士，其等級通常為3-6。Some stone giants develop special abilities related to their environment. Called elders, these stone giants have Charisma scores of at least 15 and spell-like abilities, which they use as 10th-level sorcerers. Once per day they can use stone shape, stone tell, and either transmute rock to mud or transmute mud to rock (DC 17). The save DC is Charisma-based. One in ten elders is a sorcerer, usually of 3rd to 6th level.	pf 三種類法術能力（施法者等級10）。石巨人長老獲得+1挑戰等級。 three spell-like abilities (CL 10th). Stone giant elders add +1 to their CR.
s_gnt_se_hr_splk="塑石術，石言術，化石為泥或化泥為石。"
s_gnt_se_d=[[
年長的石巨人會離開它們的部落，這是它們晚年中的一段重大時期，它們會選擇隱居或嘗試融入其他類人生物文明之中。

經過這種數十年的自我流放，那些回來的石巨人就成為了石巨人長老。

這些石巨人長老發展出一些與其環境相關的特殊能力，還能如術士一樣施展這些能力。
]]


-- 精類		Fey


s_sprite	= "小妖精"
s_sprite_c	= "這個輕盈而小巧的生物，看起來就像一個有著纖細的蛾子翅膀和細長耳朵的人。"
s_sprite_d	= [[小妖精是隱居的妖精。它們以自己的方式對抗邪惡保護家園。小妖精聚居在森林深處，守護著大自然。一個部族的小妖精會認為它們自己是它們領地內某個特定的人物、地點或生物的保護者，即便其實際上並不需要保護。

小妖精的身體天生會發光，不過小妖精能按自己的意願改變其顏色和亮度。在死亡後不久，小妖精的身體就會融化成閃亮的蒸汽。小妖精是最小的精類之一，站起來僅高9寸，很少超過1或2磅重。

小妖精使用類法術能力與迷你武器來進行戰鬥。它們喜歡使用埋伏和其他計謀遠勝於正面衝突。]]

s_sprite_e	= [[小妖精在許多方面比大多數精類要更加原始。它們享受彼此陪伴，但不信任其他精類，並認為任何不是它們要選擇保護的類人生物或其他生物都是要對它們不利的。就算是動物也通常被看作是危險的。這很大程度上是由於它們的小體型容易讓它們成為捕食者的目標所致。因此小妖精對於危險通常的第一反應都是逃跑——用它的類法術能力耽擱或混亂追捕者，然後依賴其飛行速度和體型來使其最終得以逃離。

雖然小妖精本身矇昧而原始，但它們對所有魔法事物都有著旺盛的好奇心。它們特別感興趣有著巨大潛在魔法力量的地點，比如古代廟宇的廢墟。這種好奇心使它們意外的能接受充當魔寵的角色。一個5級的擁有進階魔寵專長的混亂中立施法者，可以將小妖精作為魔寵。]]


s_nymph		= "寧芙"
s_nymph_c	= "一個絕美的身影自水中升起，尖尖的長耳生在頭的兩側，如此完美的容顏令人胸中作痛。"
s_nymph_d	= [[寧芙，也稱為水妖精，不僅是自然界美麗的化身，同時也是野生密境的守護人。她們擁有令人無法抵擋的美貌，以至於對她們隨意的一瞥便能使看見她們的人立刻目盲。

寧芙身高和體重與女性精靈差不多。寧芙說木族語和通用語。

許多人尋求寧芙的美麗，枉自丟掉了性命；更多人被寧芙的美麗所懾，陷入迷戀與瘋狂無法自拔。

但寧芙並不是殘忍的生物——她是大自然最純美祕境的守衛者，對那些尊重她與她的家園的人心懷善意，甚至會對某個人表現好感，讓他帶走她的魔法贈禮。

然而，那些試圖侵犯或傷害她和她家園的人很快會發現，她的美貌背後隱藏著自然守護者的強大力量，用來自保綽綽有餘。]]


s_pipes="牧笛"
s_pipes_d=[[半羊人能用他們的牧笛演奏多種魔法旋律。

演奏時，所有處於60英尺擴散範圍內的生物（半羊人除外）都必須透過DC13的意志檢定，否則會受到魅惑人類、睡眠或驚恐術的法術效果影響（施法等級10；半羊人可選擇旋律和效果）。

本能力的豁免檢定DC基於魅力。任何透過意志檢定的生物，24小時內不受同樣效果影響。

通常一群半羊人中只有一個攜帶牧笛。如果落入其它生物手中，牧笛會失去特殊能力。]]-- pf 薩特羊人可以用牧神笙吹出縈繞的旋律來強化他的魔法。他吹奏時，60尺半徑內的所有生物必須透過ＤＣ１８的意志豁免，否則受到魅惑人類（Charm Person）、恐懼術（Fear）、睡眠術（Sleep）或暗示術（Suggestion）的影響，效果取決於薩特羊人吹奏何種旋律。成功透過任何一種旋律的意志豁免的生物免疫同一組牧神笙的效果２４小時，但薩特羊人的其他類法術能力仍然正常影響他。吹奏牧神笙不消耗薩特羊人的每日類法術能力次數，如果他失去了牧神笙，他依然可以施展通常的能力。牧神笙總是精製品，薩特羊人可以用一星期時間製作一個新的。此能力的豁免ＤＣ基於魅力。A satyr can focus and empower his magic by playing haunting melodies on his panpipes. When he plays, all creatures within a 60-foot radius must make a DC 18 Will save or be affected by charm person, fear, sleep, or suggestion, depending on what tune the satyr chooses. A creature that successfully saves against any of the pipes' effects cannot be affected by the same set of pipes for 24 hours, but can still be affected by the satyr's other spell-like abilities as normal. The satyr's use of his pipes does not count toward his uses per day of his spell-like abilities, and if separated from them he may continue to use his standard abilities. The pipes themselves are masterwork, and a satyr can craft a replacement with 1 week of labor. The save DC is Charisma-based.

s_satyr="半羊人"
s_satyr_c="這個咧嘴微笑的英俊男子長著一雙山羊腿，彎曲的羊角從他額頭兩側伸出。"
s_satyr_fav_cls="半羊人熱愛音樂，具有音樂天賦，牧神笙因他們而得名。半羊人可以用牧神笙編織出千變萬化的魔法旋律來魅惑他人。"
s_satyr_traits=[[
<b c=tg>+2敏捷，+2體質，+2智力，+2感知，+2魅力：</b>除了不太強壯，半羊人天生優雅靈活，感官敏銳，在各方面都表現不俗。

<b>種族生命骰：</b>半羊人初始擁有5個妖精等級，給予它5d8生命骰。

<b>種族技能：</b>半羊人的妖精等級給予它8 x (2 + 智力調整值)的技能點數。其本職技能為唬騙、隱藏、潛行、偵察、聆聽、表演、知識(自然)。它在隱藏、潛行、偵察、聆聽、表演檢定上有+4種族加值。

<b>種族專長：</b>半羊人的妖精等級給予它2個專長。半羊人獲得機警作為獎勵專長。

<b>防禦：</b>+4天生防禦加值。

<b>天生武器：</b>抵撞（1d6）。{hlp_nwpn}

<b>武器擅長：</b>擅長簡易武器、短弓。

<b>特殊能力：</b><t=@pwr_pipes c=fc_b>牧笛</t>，<t=@pwr_dr5_cdir c=fc_b>傷害減免5/寒鐵</t>。
]]-- 基本攻擊加值+2，基本豁免加值強韌+1，反射+4，意志+4。a base attack bonus of +2, and base saving throw bonuses of Fort +1, Ref +4, and Will +4.
s_satyr_langs=[[
<b>初始語言：</b>木族語。
<b>額外語言：</b>通用語、精靈語、侏儒語。

<c=twc>半羊人講木族語，並有許多會說通用語。</c>
]]
s_satyr_m=[[
半羊人在一些地區被稱為牧神，他們是享樂放蕩的生物，生活在森林深處，熱愛美酒、音樂和肉體愉悅，喜歡勾引未經人事的少女和牧童。

半羊人通常擔任著森林生物守護者的職責，他們可以用牧神笙編織出千變萬化的魔法旋律來魅惑他人。

半羊人的頭髮是紅色或棕色，而蹄和角是深黑色，身高和體重與半精靈差不多。

半羊人講木族語，並有許多會說通用語。
]]
s_satyr_d=[[
半羊人，也稱為薩特或薩特羊人，在一些地區被稱為牧神。他們是享樂放蕩的生物，生活在森林深處，熱愛美酒、音樂和肉體愉悅，喜歡勾引未經人事的少女和牧童。

儘管半羊人擁有健壯而陽剛的男子身軀，他們誘騙少女的主要資本是音樂天賦，牧神笙因他們而得名。半羊人可以用牧神笙編織出千變萬化的魔法旋律來魅惑他人。

除了永無休止的嬉戲玩樂之外，半羊人通常擔任著森林生物守護者的職責。
]]
s_satyr_eds={
[race_ed_dd1]=[[
半羊人在一些地區被稱為牧神，他們是享樂放蕩的生物，生活在森林深處，熱愛美酒、音樂和肉體愉悅，有著浪蕩不羈和油嘴滑舌的名聲，喜歡勾引未經人事的少女和牧童，把事後一大堆尷尬的解釋和意外的懷孕留給人家去操心。

與半羊人云雨過後生下的孩子總是純血半羊人，通常很快就會被他放蕩的親族拐走。儘管半羊人重視自己的愉悅遠勝於他人的權利，他們對被引誘者沒有惡意。

儘管半羊人擁有健壯而陽剛的男子身軀，他們誘騙少女的主要資本是音樂天賦。牧神笙因他們而得名。半羊人可以用牧神笙編織出千變萬化的魔法旋律來魅惑他人，讓他們掉進他的慾望陷阱之中。

除了永無休止的嬉戲玩樂之外，半羊人通常擔任著森林生物守護者的職責，那些成功把半羊人的慾望轉為憤怒的傢伙會發現自己面對著一位被危險生物圍繞著的牧神。
]],
