]],
[race_ed_dd3]=[[
]],
[race_ed_dd4]=[[
]],
[race_ed_phy]=[[
半羊人擁有健壯而陽剛的男子身軀，頭髮是紅色或棕色，而蹄和角是深黑色。

半羊人的身高和體重與半精靈差不多。
]],
[race_ed_btl]=[[
半羊人敏銳的感官讓他在戶外幾乎不可能被突襲。相反，憑著他們天生的優雅與靈活，半羊人可以潛行到沒有小心觀察周圍荒野的旅行者身邊。

一旦戰鬥展開，徒手的半羊人會以有力的抵撞進行攻擊。預期到可能遇到麻煩的半羊人，會裝備弓和匕首，並在敵人接近前就從躲藏處射箭削弱對手。
]],
