-- 人形怪物	Monstrous Humanoid


s_powerful_charge		="強力衝刺"
s_powerful_charge_d		=[[牛頭人的戰鬥通常以衝鋒對手開始，低下頭用強有力的雙角衝進戰場。

每場戰鬥的首次衝鋒額外加上2倍抵撞傷害。]]-- 這次攻擊除了衝刺動作本身的優勢和風險外，還將以+9的攻擊加值進行單一一次抵撞攻擊，並造成4d6+6點傷害。In addition to the normal benefits and hazards of a charge, this allows the beast to make a single gore attack with a +9 attack bonus that deals 4d6+6 points of damage.

s_natural_cunning		="天性狡猾"
s_natural_cunning_d		=[[雖然牛頭人不是特別聰明，但它們擁有天生的狡猾和邏輯能力。

這使得它們免疫迷宮術，絕不會迷路，還能追蹤敵人。

此外，它們永遠不會陷入措手不及狀態。]]

s_minotaur="牛頭人"
s_minotaur_c="有著健壯的人類軀體和噴氣的公牛頭顱，這個生物的雙蹄來回刨地，像是準備衝鋒。"
s_minotaur_fav_cls=""
s_minotaur_traits=[[
<b c=tg>+8力量，+4體質，<c=tr>-4智力，-2魅力：</c></b>牛頭人非常強壯堅韌，但是它們生於詛咒，心智扭曲，極其記仇。

<b>種族生命骰：</b>牛頭人初始擁有6個人形怪物等級，給予它6d8生命骰。

<b>種族技能：</b>牛頭人的人形怪物等級給予它9 x (2 + 智力調整值)的技能點數。其本職技能為跳躍、搜尋、偵察、聆聽、威嚇。它在搜尋、偵察、聆聽檢定上有+4種族加值。

<b>種族專長：</b>牛頭人的人形怪物等級給予它3個專長。

<b>防禦：</b>+5天生防禦加值。

<b>天生武器：</b>抵撞（1d8）。{hlp_nwpn}

<b>武器擅長：</b>擅長簡易武器、巨斧。

<b>特殊能力：</b><t=@pwr_powerful_charge c=fc_b>強力衝刺</t>，<t=@pwr_natural_cunning c=fc_b>天性狡猾</t>，<t=@pwr_scent c=fc_b>靈敏嗅覺</t>。
]]-- +6的基本攻擊加值，基本豁免加值為強韌+2，反射+5，意志+5。a base attack bonus of +6, and base saving throw bonuses of Fort +2, Ref +5, and Will +5.
s_minotaur_langs=[[
<b>初始語言：</b>通用語、巨人語。
<b>額外語言：</b>獸人語、地精語、土族語。

<c=twc>牛頭人說巨人語。</c>
]]
s_minotaur_d=[[
牛頭人有著壯碩的人類軀體和公牛的頭顱，站立時超過7英尺高，體重約700磅。

沒有什麼像牛頭人一樣記仇。很多文化中都有關於牛頭人起源的傳說，提到被輕視的記仇神祗將人類扭曲形態，奪走心智與美貌，安上牛頭來作為懲罰。

但絕大多數現代牛頭人對此嗤之以鼻，認為自己不是神的玩物，而是被稱為巴風特的強大殘忍惡魔領主製造的典範生物。
]]
s_minotaur_eds={
[race_ed_dd1]=[[
沒有什麼像牛頭人一樣記仇。無數世紀前遭到文明種族的輕視，因神降下的詛咒而生，牛頭人為了報復最細小的不敬，無論是真實還是妄想，不斷的獵殺，屠戮和吞吃其他次等的類人生物。

很多文化中都有關於牛頭人起源的傳說，提到被輕視的記仇神祗將人類扭曲形態，奪走心智與美貌，安上牛頭來作為懲罰。但絕大多數現代牛頭人對此嗤之以鼻，認為自己不是神的玩物，而是被稱為巴風特的強大殘忍惡魔領主製造的典範生物。
]],
[race_ed_dd2]=[[
傳統的牛頭人的巢穴是個迷宮。包括用來迷惑他人的正式迷宮，無意產生的迷宮——比如城市下水道，以及自然形成的迷宮，比如交錯的洞穴和地底通道。

藉助他們天生的狡猾，牛頭人用它們的迷宮巢穴困住前來找麻煩的粗心敵人和誤打誤撞的迷路者，慢慢地獵殺它們。只有徹底征服了絕望的目標時，牛頭人才會予以最後一擊。

當對付一群敵人時，牛頭人通常會放走一個活口，來散佈恐怖並引誘其他的敵人來獵殺自己。當然對於牛頭人來說，這些想當英雄的傢伙味道好極了。
]],
[race_ed_dd3]=[[
牛頭人也可能被更強大的怪物和邪惡生物統領，只有任其獵殺捕食它們就沒有怨言。

一般來說這意味著守衛強大的物件和重要的地點，或者是普通的傭兵任務，獵殺主人的敵人。
]],
[race_ed_dd4]=[[
]],
[race_ed_phy]=[[
]],
[race_ed_btl]=[[
牛頭人偏好近戰，因為此時它們的強大力量能徹底發揮作用。

牛頭人戰鬥起來很直接，戰鬥一開始就用可怕的犄角捅穿最近的敵人。
]],
[race_ed_soc]=[[
]],
[race_ed_rel]=[[
]],
[race_ed_aln]=[[
]],
[race_ed_adv]=[[
]],
[race_ed_nam]=[[
]],
}


s_centaur_charge		="人馬衝鋒"
s_centaur_charge_d		="人馬使用長武器進行衝鋒時會造成雙倍傷害，就如同馬背上的騎士一樣。"-- 長槍 lance

s_centaur="人馬"
s_centaur_c="這種生物的上半身是一個古銅色面板、經驗豐富的戰士，下半身則是一匹皮毛光滑的戰馬。"
s_centaur_fav_cls="人馬生活在遼闊的平原或可怕的森林邊緣，它們是傳奇的獵手和戰技純熟的戰士。"
s_centaur_traits=[[
<b c=tg>+8力量，+4敏捷，+4體質，+2感知，<c=tr>-2智力：</c></b>人馬強壯堅韌，身體靈活又警覺，但通常愚鈍且野蠻。

<b>種族生命骰：</b>人馬初始擁有4個人形怪物等級，給予它4d8生命骰。

<b>種族技能：</b>人馬的人形怪物等級給予它7 x (2 + 智力調整值)的技能點數。其本職技能為聆聽、潛行、偵察、生存。

<b>種族專長：</b>人馬的人形怪物等級給予它2個專長。

<b>防禦：</b>+3天生防禦加值。

<b>武器和盔甲擅長：</b>擅長簡易武器、軍用武器（重刃、弓）。

<b>特殊能力：</b><t=@pwr_centaur_charge c=fc_b>人馬衝鋒</t>。
]]
s_centaur_langs=[[
<b>初始語言：</b>木族語、精靈語。
<b>額外語言：</b>通用語、侏儒語、半身人語。

<c=twc>人馬一般只會說木族語和精靈語，相對聰明的個體也會說通用語。</c>
]]
s_centaur_d=[[
人馬是傳奇的獵手和戰技純熟的戰士，它們是半人半馬的生物。

人馬是一個古老的種族，只能慢慢接受現代世界。極少數情況下，某些進步領袖所領導的整個部族都會和類人生物的群落進行交易甚至結盟。

雖然大多數人馬依然生活在遼闊的平原或可怕的森林邊緣，但是也有許多人拋棄了祖先孤立的生活方式而進入大都市生活。
]]
s_centaur_eds={
[race_ed_dd1]=[[
]],
[race_ed_dd2]=[[
]],
[race_ed_dd3]=[[
]],
[race_ed_dd4]=[[
]],
[race_ed_phy]=[[
人馬是半人半馬的生物，它們像重型馬一樣大，但是要比重型馬高很多而且還要稍微重一些。

人馬通常出現在文明的邊緣地帶，這些堅忍的生物外表上體現出很大差異，它們的膚色黝黑，和附近地區的人類相似，但是下半身卻有著馬匹的色澤。

人馬的髮色和瞳色通常是深色，臉部寬闊，而身體的大部分則受到下半身體型的影響。所以一般來說人馬站立超過7尺高，重量超過2000磅，它們的體型差異較大——從瘦小的平原行者到壯實的山地獵手。

人馬一般來說能活60歲。人馬說木族語和精靈語。
]],
[race_ed_btl]=[[
]],
[race_ed_soc]=[[
]],
[race_ed_rel]=[[
人馬遠離其他種族，同類之間也有爭端。人馬是一個古老的種族，只能慢慢接受現代世界。

極少數情況下，某些進步領袖所領導的整個部族都會和人形生物的群落進行交易甚至結盟——比如精靈，但有時是侏儒、人類或矮人。

許多種族小心提防著人馬，大部分是由於傳說中人馬野蠻而領土意識很強，並且它們和頑固的殖民者與擴張性國家常常產生強烈的衝突。
]],
[race_ed_aln]=[[
]],
[race_ed_adv]=[[
雖然大多數人馬依然生活在遼闊的平原或可怕的森林邊緣，但是也有許多人拋棄了祖先孤立的生活方式而進入大都市生活。

通常這些自由而英勇的人馬被認為遭到了部落放逐，下定決心離開它們的部族。
]],
[race_ed_nam]=[[
]],
}


s_medusa	= "梅杜莎"
s_medusa_c	= "這位纖細、冶麗的女子有著一對閃爍著詭異光采的雙眼，還有一頭嘶嘶作響的蛇發。"
s_medusa_d	= [[梅杜莎，也稱為蛇髮女妖，是一種外型似人，但有著一頭蛇發而非長髮的生物。若是梅杜莎戴著某物來蓋住她那盤卷糾結的蛇發，從三十呎或更遠處看去，她是很有可能被誤認為美麗的女子的——若她以衣物遮掩住臉部與頭部，即使在更近的距離內都可能被誤認為人類。

梅杜莎有5到6尺高，並且差不多和人類一樣重。梅杜莎說通用語。

梅杜莎習慣將自己的真面目偽裝起來用各種說辭和騙術讓目標確認沒有危險，直到受害者進入其石化凝視射程範圍之內。梅杜莎會使用一般的武器來攻擊那些避開其視線或倖存下來的敵人，同時利用其劇毒的蛇發來攻擊鄰近的敵人。]]--在30尺距離之外（或更近，如果它的臉遮起來的話）梅杜莎看起來和人類毫無二致。此生物通常穿著能加強身體曲線的衣服，並用兜帽或面紗遮起臉。

s_medusa_e	= [[梅杜莎以謊言與偽裝來隱藏她們的面容，直到距離近得足以讓她們對敵人施展石化凝視，但同時她們也性喜從遠處以箭矢打擊敵人，引誘他們掉入陷阱之中。

有少數梅杜莎酷愛用這些悲慘的受害者所製成的複雜裝飾來妝點她們沼澤中的巢穴，但是大多數的梅杜莎則會小心地隱藏前一個受害者存在的跡象，這樣下一個敵人才不會先對她們的存在心懷警戒。

由於習於隱匿自己的樣貌，在城市中生活的梅杜莎經常是遊蕩者，而她們荒野中的同類則會偽裝成巡林客或是追蹤者。然而，那些最傳奇也最惡名遠播的梅杜莎，則具有吟遊詩人或者牧師的等級。

由於她們風姿綽約又聰慧機敏，生活在都市的梅杜莎經常會與盜賊公會或者其他地下世界的黑暗勢力有所關聯。梅杜莎可能會跟目盲的生物或者有智慧的不死生物結成同盟，因為這兩者皆免疫她的石化凝視。

會施法的梅杜莎通常是先知或者預言者，有著宣告遠播的強大能力或惡名遠播的過往，並居住在偏僻之地。這些作為先知的梅杜莎對於她們的職責相當投入，若贈予她們足夠份量的贈禮與合適的奉承，她們所能告知的祕密會相當地有用。

當然，這些強大生物的巢穴中毫不避諱地擺放著那些無禮冒犯之人的塑像，因此想從她們身上探尋知識的人會被告誡要在這樣的會面中保持謹慎。

所有已知的梅杜莎都是女性。少見地，梅杜莎可能會選擇一名雄性的人形生物作為她的伴侶，通常是藉由愛情靈藥或者類似法術的幫助，而她會非常小心不要石化這名愛情的犯人——至少直到她開始厭煩他的陪伴為止。]]


s_harpy		= "鷹身女妖"
s_harpy_c	= "這個生物看起來像是一個外表狂野的女性，但是長著襤褸的翅膀和鳥爪一樣的雙腳。"
s_harpy_d	= [[鷹身女妖，也稱為人面鳥妖，這種生物看起來像是一個外表狂野的女性，但是長著襤褸的翅膀和鳥爪一樣的雙腳。

鷹身女妖偏愛以她們充滿魔力的歌聲誘惑那些不幸的旅行者，然後將他們置於無法形容的折磨中。只有當鷹身女妖厭倦了她的新“玩具”時才會讓他們解除這些苦難—也就是把他們殺了吃掉。

鷹身女妖喜歡穿戴從受害者身上取得的珠寶或飾品，因為她們易於沉湎於人類飾品的閃亮光芒中。如果靠近這些生物的話，會聞到她們身上散發出被害者的屍臭。所以她們很少讓未被迷魂的生物太過接近，免得他們聞到羽毛上腐爛的氣息。因此許多鷹身女妖都會在身上塗抹香料或香油。

出現在不同地域的鷹身女妖在外表上截然不同。一些看起來像是禿鷲和女性的混合體，而另一些則有獵鷹一般威嚴的羽毛。一些生活在與世隔絕的熱帶島嶼的鷹身女妖甚至有鸚鵡一般五彩的羽毛。]]

s_harpy_e	= [[鷹身女妖通常被視作墮落腐敗的邪惡之物，她們瞭解生物如何思考和行動。這種理解在她們尋找最愛的獵物時讓她們佔盡優勢。

雖然野外的生物很容易就成為她們迷魂曲的犧牲品，但其實這些卑鄙的鳥人更喜歡品嚐那些以各種複雜情緒為佐料的智慧生物。簡單的獵物味如嚼蠟。

雖然極度野蠻且對自己的行為從無悔改，大多鷹身女妖定居於人型生物社會附近，並且樂於周旋於那些被她們視作“食物”的生物之間。


<b>鷹身女妖射手</b>
殘酷的獵人和遊蕩的強盜，鷹身女妖射手被訓練成精通遠端戰鬥的戰士。鷹身女妖射手經常作為僱傭兵，把她們的服務賣給出價最高的人。在沒有工作的時候，她們會以攔路強盜的身份來維持生計，迫使來往商隊支付保護費。]]


s_hag		= "鬼婆"
s_hag_d		= [[雖然不同的鬼婆擁有獨特的外貌與習性，但也有許多共同點，它們都有著乾癟的醜老太婆的外型，佝僂的身軀掩飾了可怕的力量與敏捷的動作。

鬼婆十分強壯。它們對法術具有天然的抗力，並且會施展自己的魔法。鬼婆常常集結成戰團，每個群體通常包含各種鬼婆，這樣便可以使用各種類的能力。

鬼婆說巨人語和通用語。]]


-- 異界生物	Outsider


s_celestial_creature	= "天界生物"
s_celestial_creature_d	= [[天界生物居住於上層位面，善良的領域，儘管在主物質界能找到與它們相類似的生命。它們比它們在俗世對應生物們更加華麗漂亮。

天界生物通常展現出金屬般的色彩 (一般為銀色，金色或白金色) 。它們可能會被誤認為是天界生物與非天界生物交配產生的半天界或者更強的生物。]]


s_fiendish_creature		= "煉獄生物"
s_fiendish_creature_d	= [[煉獄生物居住在邪惡的下層位面，但在主物質位面也能找到與它們類似的生命。和俗世間的類似生物相比，它們擁有更加可怕的外貌。]]


s_half_celestial	= "半天界生物"
s_half_celestial_d	= [[不論其形態，半天界生物看起來總是令人賞心悅目，它們有金色的面板，閃亮的眼睛，天使般的翅膀，或其他能顯示它們高貴血統的標誌。]]


s_half_fiend	= "半煉獄生物"
s_half_fiend_d	= [[不論其形態，半煉獄生物總是不堪入目，它們有黑色的鱗片，犄角，閃爍著紅光的眼睛，蝙蝠一樣的翅膀，惡臭的體味，或者其他能顯示它們受到邪惡汙染的特徵。]]


s_angel		= "天使"
s_angel_d	= [[天使是天界生物的一支，或者是善良的異界生物。他們居住在善良陣營的外位面。

天使可以是任意善良陣營。無論他們的陣營為何，天使永遠不撒謊，欺騙或偷竊。他們所有的行為都完美無缺的使人感到敬佩，這些行為經常顯示他們是所有天界生物中最老練，並最可信賴的。

所有的天使都長的十分秀麗，儘管他們的容貌差異很大。

天使說天界語，煉獄語和龍語，儘管他們可以通過自己的巧言能力來和幾乎任何生物交流。]]


s_archon	= "神使"
s_archon_d	= [[神使，也稱為亞空神族，是天界生物的一支，或者是善良的異界生物。他們居住在守序善良陣營的外位面。

神使說天界語，煉獄語和龍語。但她們可以通過自己的巧言能力來和幾乎任何生物交流。]]


s_demon		= "惡魔"
s_demon_d	= [[惡魔生活在混亂邪惡位面，他們是凶殘的化身。僅僅為了取樂，惡魔就會攻擊其他任何生物——甚至包括他們的同類。

惡魔說深淵語，天界語和龍語。]]


s_devil		= "魔鬼"
s_devil_d	= [[魔鬼是來自於守序邪惡位面的煉獄生物。

多數魔鬼身體周圍都環繞著邪惡靈氣，它們會利用這個靈氣打散戰力很強的敵人隊伍，然後再逐一擊敗各個對手。

擁有類法術能力的魔鬼會使用它們的幻術能力盡可能地欺騙和迷惑對手。它們最喜歡玩的把戲是創造一支由幻像構成的增援部隊，敵人永遠無法確定這威脅僅僅是虛假幻覺還是被召喚來加入戰鬥的真正魔鬼。

魔鬼說煉獄語，天界語，和龍語。]]


s_planetouched		= "神魔裔"
s_planetouched_d	= [[神魔裔是一種通稱，用來描述那些可將其血緣回溯到異界生物（通常是煉獄生物或天界生物）的物件。

當一個人的遺傳中擁有超自然的本質時，此效果可以延續好幾個世代之久。雖然外觀上不會像半天界或半煉獄生物那樣有著戲劇性的變化，但神魔裔仍然保留了一些特殊能力。

阿斯莫和泰夫林是最常見的神魔裔。阿斯莫是帶有天界血統的人類，而泰夫林的家譜中往往會有一些煉獄生物。]]


s_aasimar		= "阿斯莫"
s_aasimar_c		= "這個有著不尋常美貌的女子看起來像人類，給人一種冷靜，善良的感覺。"
s_aasimar_d		= [[阿斯莫，也稱神裔，通常高挑，容貌姣好而且一般都很討人喜歡。一些阿斯莫的身體特徵暗示著他們的血統，比如銀髮、金眼或異乎尋常的目光。

大部分的阿斯莫都很明確的屬於善良陣營。他們會對抗邪惡，並試圖影響他人去做正確的事。偶爾他們也會因其天界祖先的個性而做出復仇或判罰的行為，但是這很罕見。]]--pf神裔是受到天界祝福的生物，她們的外貌像是人類，卻有著指向自身上界血脈的獨有特徵。神裔幾乎總是美麗脫俗，而她們也可能沾染到人性的各個方面——儘管邪惡之徒只是少數而已，她們並不全是善良之輩。Creatures blessed with a celestial bloodline, aasimars seem human except for some exotic quality that betrays their otherworldly origin. While aasimars are nearly always beautiful, something simultaneously a part of and apart from humanity, not all of them are good, though very few are evil.
s_aasimar_fav_cls="阿斯莫通常喜歡公平而直接的競賽。然而，在對抗邪惡的敵人時，他們會抱著堅定的信念戰鬥至死。"
s_aasimar_traits=[[
<b c=tg>+2感知，+2魅力：</b>阿斯莫富有洞察力、自信且風度翩翩。

<b>技能熟練：</b>偵察、聆聽檢定有+2種族加值。]]
.."\n\n"..xs_lbl("s_res_ace_5")
.."\n\n".."<b>類法術能力：</b>每天可施展一次<t=@pwr_sp_lt_3 c=fc_b>晝明術</t>，施法者等級等同角色等級。"-- 種族專長：阿斯莫通過其職業等級獲取專長。	Racial Feats: An aasimar gains feats according to its class levels.
s_aasimar_langs=[[
<b>初始語言：</b>通用語、天界語。
<b>額外語言：</b>龍語、矮人語、精靈語、侏儒語、半身人語、木族語。

<c=twc>阿斯莫說通用語和天界語。</c>
]]
s_aasimar_eds={
[race_ed_dd1]=[[
神裔是擁有天界或其他善良異界顯著血統的人類。雖然不全是仁慈之輩，神裔明顯地有著行善棄惡的傾向，他們對天界的信仰或認同非常堅定。

神裔的遺傳可以潛藏數代，卻突然地出現在雙親分明是人類的小孩身上。多數社會把神裔的降生視為吉兆；不過也有記載表明，有些神裔利用自己的身份和名望犯下殘虐無道的暴行，顛覆了人們對他們普遍的印象。“我永遠是你最不會懷疑的人”，這是那些邪惡神裔信奉的至理。他們往往有著傑出市民或虛偽英雄的一副面孔，將墮落的另一張面孔深深掩藏。好在這些反例都是鳳毛麟角。
]],
[race_ed_dd2]=[[
阿斯莫是有著天界或者其他善良的異界先祖血統象徵的人類。阿斯莫並不都是善良的，但是善良是他們的本性，並且他們會被有著善良信仰或者組織的天界夥伴吸引。

阿斯莫的血統會一連幾代地被隱藏，但卻會突然在雙親明顯為人類的孩子身上顯現。大部分組織表明，阿斯莫出生時會伴隨好兆頭。

阿斯莫看起來幾乎跟人類一樣，除了一些身體上的小細節顯露了他那不一般的血統。標準的阿斯莫生物頭髮有著金屬光澤，不一般的瞳色和膚色或者甚至發出金色光環。
]],
[race_ed_phy]=[[
除了某些揭示非凡血統的細節特徵，神裔看上去和人類並無區別。

典型的神裔特徵包括金屬光澤的頭髮、寶石瞳孔的眼睛、細膩皎潔的肌膚，甚至還有頭頂閃耀的金色光環。
]],
[race_ed_btl]=s_aasimar_fav_cls,
[race_ed_soc]=[[
很難說神裔擁有自己的社會。他們作為人類的一枝，適應了周遭環境，並活躍在矯正不公、撫平傷慟等與社會陰暗面鬥爭的舞臺上。

在某些暴政大行其道的國度，這些行為使他們站到了法律的對立面；但神裔在必要時也會謹慎而機智，使自己能夠避免受到壓迫者的注意。

雖然邪惡神裔可能獨行、或是建立讓自身罪孽得以遁形的地下結社，正氣凜然的神裔們通常會聚集在善良組織的旗下，尤其（但非絕對）是教會等宗教團體。
]],
[race_ed_rel]=[[
神裔在人類社會中最為常見，他們也最習慣生活在人類中。對那些天界血統比較淡薄的神裔來說尤為如此。

為何天界更青睞人類而非其他種族依然原因不明，可能是因為人類的遺傳基因與其最為親和、適於完成向神裔的進化。又或許，是那些種族的特徵過於稜角分明，難以改變也說不定。無論其他種族是否與上層位面的存在有過“親密接觸”，他們之間確實少有子嗣、更未出現過神裔。

不過，雖然神裔更偏向人類社會，他們也能自如地生活在其他任何環境中。他們擁有與生俱來的優雅社交性，風度翩翩而又值得信賴。他們和半精靈關係親密，因為雙方有著人類近親的共性；但和半獸人之間相對冷淡，因為對方難有耐性來應對神裔過分華美的用辭和容顏。精靈執政者有時會驅逐神裔，並責難他們過於依靠天生嫵媚來掩蓋失禮之舉。也許在所有種族中侏儒對神裔最為傾心，對他們多變的容貌和神祕的血統長久地保持好奇和尊重。
]],
[race_ed_aln]=[[
神裔是最傾向於善良陣營的種族，但這並非絕對，也有神裔背棄公正、投身於墮落的無底深淵。

大多數神裔崇拜象徵榮耀、英勇、守護、治癒和救難的神祇，或信仰家園、社群或家庭等質樸的概念。也有些神裔走上了藝術、音樂和知識之道，從美中尋找真理和智慧。
]],
[race_ed_adv]=[[
由於對人類社會的歸屬感不足、或感召於自身偉大使命，常有神裔成為冒險者。

牧師和聖騎士是他們最多見的選擇，而吟遊詩人和術士這些奧術職業中神裔的身影也不鮮見。神裔野蠻人很稀罕，但一旦降生於某些部落，他們往往會領導和鼓舞整個氏族皈依天界圖騰之下。
]],-- 牧師、先知...術士和召喚師	, oracles,	summoners
[race_ed_nam]=[[
<c=twa>常見男名：</c>
阿里申（Aritian），貝廷（Beltin），塞南（Cernan），克隆威爾（Cronwier），厄蘭（Eran），艾拉敏（Ilamin），毛德利（Maudril），奧克林（Okrin），帕蘭特（Parant），圖洛（Tural），衛蘭（Wyran），塞坎（Zaigan）。

<c=twa>常見女名：</c>
阿柯恩（Arken），阿欣諾（Arsinoe），達薇娜（Davina），德琳瑪（Drinma），艾美薩（Imesah），瑪索吉（Masozi），妮婕娜（Nijena），妮拉莫（Niramour），翁德萊（Ondrea），莉雅拉（Rhialla），瓦爾提拉（Valtyra）。
]],
}


s_tiefling		= "泰夫林"
s_tiefling_c	= "這個瘦長高挑的男人冷笑著拔出自己的劍，頭上小小的角和身後帶刺的尾巴說明他並非尋常人類。"
s_tiefling_d	= [[泰夫林，也稱魔裔或提夫林，是沾染魔族血統的凡人，起源不一、常出現在類人生物的社群中。

其他種族很少信任他們，而這種同情的缺少恰恰又常逼泰夫林尋求血脈中墮落部分的支援。

少數泰夫林將這種與黑暗慾望的搏鬥視為踏上英雄之旅的動力。]]--3r許多泰夫林和人類沒有差別。一些泰夫林有小角、尖牙、紅眼、身上瀰漫著硫磺味甚或有蹄的腳。沒有任何兩個泰夫林會長得一模一樣。泰夫林總是偷偷摸摸且虛偽狡猾的。他們喜歡發動突襲，並會盡可能地避開公平的戰鬥。Many tieflings are indistinguishable from humans. Others have small horns, pointed teeth, red eyes, a whiff of brimstone about them, or even cloven feet. No two tieflings are the same. Tieflings are sneaky, subtle, and generally conniving. They prefer to strike from ambush and usually avoid a fair fight if they can.
s_tiefling_fav_cls="泰夫林總是偷偷摸摸且虛偽狡猾的。他們喜歡發動突襲，並會盡可能地避開公平的戰鬥。"
s_tiefling_traits=[[
<b c=tg>+2敏捷，+2智力，<c=tr>-2魅力：</c></b>泰夫林靈活機智，但天性怪異。

<b>技能熟練：</b>唬騙、躲藏檢定有+2種族加值。]]
.."\n\n"..xs_lbl("s_res_cef_5")
.."\n\n".."<b>類法術能力：</b>每天可施展一次<t=@pwr_sp_dk_2 c=fc_b>黑暗術</t>，施法者等級等同角色等級。"-- 種族專長：泰夫林通過其職業等級獲取專長。	Racial Feats: A tiefling gains feats according to its class levels.
s_tiefling_langs=[[
<b>初始語言：</b>通用語、煉獄語。
<b>額外語言：</b>龍語、矮人語、精靈語、侏儒語、地精語、半身人語、獸人語。

<c=twc>泰夫林說通用語和煉獄語。</c>
]]
s_tiefling_eds={
[race_ed_dd1]=[[
與凡人差異不多的魔裔是人類和魔族的後代。超凡的血腥特徵使他們被世人恐懼和背棄。

由於造成他們出生的詛咒因緣常發生在數代之前，多數魔裔並不知曉自己的煉獄主人。血脈的汙痕持續長久，常在出生時或不久後事與願違地強力顯現。

儘管有著魔族的容貌和下界的起源，魔裔與人類同樣主宰著自己的命運；很多魔裔確實接受了黑暗血統並寄身於煉獄之力，其他人則拒絕自己的黑暗傾向。血脈的力量幾乎令每個魔裔心中湧動的破壞和狂怒，但哪怕是魅魔的後裔也能成為聖者，深淵領主的子孫也會當上英雄。
]],
[race_ed_dd2]=[[
繼承了惡魔，魔鬼或其他邪惡異界生物所玷汙的人類血脈，泰夫林為它們怪異的外貌和習性為他人所非議，更使得這些魔裔只能在文明社會的陰暗角落和邊緣區域掙扎求生。即使並非天生邪惡，它們成長的軌跡也往往印上被周圍的“普通”人施加的種種痛苦。

大體上看他們的形象與人類無異，只有一些小小的區別會揭露泰夫林的怪異血緣。
]],
[race_ed_phy]=[[
沒有兩個魔裔長相相似；他們血脈中流淌的魔族之血各不相同，但都給他們帶來了一些煉獄特徵。

魔裔的外表是可能生有小角、尖尾、異色雙眼的人類，可能長著獠牙、細翼、利爪，或者帶有血腥、硫磺般的氣味。

通常這些特徵都可以追溯到魔裔的祖先身上；但即便如此，人類與魔族血統的混合也無常理可循、變化多端，使得魔裔外觀奇妙，從脫俗美麗到令人作嘔。
]],
[race_ed_btl]=s_tiefling_fav_cls,
[race_ed_soc]=[[
主物質位面的魔裔很少會建立自己的集落或要塞，而是居住在出生地周邊的土地上。多數社會將魔裔看成怪物或詛咒，但在那些頻繁與所召喚的魔族交流的文化中、尤其在崇拜惡魔、魔鬼或其他邪惡異界來客是合法行為的地區，魔裔可能更易為人接納，甚至被視為來自魔族大君的祝福。

魔裔極少能遇到自己的同族，也因此常隨人類親族的文化習俗長大成人。在其他位面，魔裔會組成自己的聚落。但這些聚落也不太平——魔裔血統來源和哲學價值的多樣性是衝突之源，各種派系的力量此消彼長，唯有最審時度勢者才能佔據優勢。只有擁有共同血脈的魔裔之間，或決定摒棄自身自私、扭曲和邪惡天性的魔裔之間才能存在真正的相互信賴、同仇敵愾，並攜手在同類中贏取立足之地。
]],
[race_ed_rel]=[[
魔裔飽受來自其他種族的歧視，常被看作魔族汙穢、邪惡孽種、洪水猛獸以及異界詛咒。

文明種族常疏遠或排斥他們，而蠻荒之民單純地恐懼和拒絕他們，除非被迫屈從。但半精靈、半獸人以及——最不可思議的——神裔，會把他們看作親人，認為他們同樣是不被自己生身之地所容之人。

對於魔裔天性邪惡的普遍觀點（雖是偏見但也許正是如此）使他們難以在多數主物質位面的文化中立足，除了那些常與外位面有跨界聯絡的國家。
]],
[race_ed_aln]=[[
儘管擁有魔族遺傳並飽受偏見之苦，魔裔確實可能是任何陣營。很多魔裔屈服於扭曲了自己心智的黑暗慾望，聽從了耳畔邪惡低語的誘惑；而那些堅定地拒絕自身起源、並主動和邪惡勢力與外界偏見鬥爭的魔裔則有種種善行。然而，更多數的魔裔單純地想在世上為自己找到安身立命之所，更傾向於從中立的視角審視自身和萬物。

雖然很多生物覺得魔裔必然崇拜魔鬼和惡魔，他們的宗教觀仍然如外貌般彼此迥異。魔裔個體可能尊崇所有神祗，但也有可能背棄一切宗教。那些因黑暗低語而墮落的魔裔會追隨各種強大的魔族大君。
]],
[race_ed_adv]=[[
魔裔極少在稱為家園的凡俗社會長期容身。而投身冒險生活也是一種逃避手段，他們希望為自己謀求更好的生活，來證明自己不被血統汙點所束縛、或對畏懼和拒絕自己的世界本身加以懲戒。

魔裔是熟練的盜賊和強大的法師，並因特別的血統而能成為強有力的術士。那些與內在邪惡同調的魔裔常會成為下界力量的牧師。
]],-- 強大的法師和魔戰士	magi
[race_ed_nam]=[[
<c=twa>常見男名：</c>
巴魯（Baru），狄利薩（Dellisar），馬德雷克（Maldrek），莫洛斯（Molos），薩文（Sarvin），舍利摩斯（Shoremoth），忒梅利斯（Temerith），沃稜（Voren），佐稜（Zoren）。

<c=twa>常見女名：</c>
阿莉薩（Allizsah），因德蘭娜（Indranna），卡西卓（Kasidra），克拉娜（Kilarra），梅麗森（Mellisan），墨德蘭（Mordren），妮莎（Nisha）。
]],
}-- 八路（Baru）


s_pc_elm_a="風元素裔"
s_pc_elm_a_c="這個蒼白柔弱的女人，頭髮隨著並不存在的微風而飄動，彷彿隨時都可能消失於周圍的薄霧之中。"
s_pc_elm_a_fav_cls="對詭計花招的熱愛和天生善於擺脫困境的能力，使得風元素裔十分適合擔當盜賊、小偷、間諜一類的角色。外表的害羞與柔弱為風元素裔的精明強幹提供了完美的偽裝，使得他們能不斷的衡量對手，分析最有效的致勝之法。"
s_pc_elm_a_traits=[[
<b c=tg>+2敏捷，+2智力，<c=tr>-2體質：</c></b>風元素裔迅捷而富有洞察力，但是身體纖弱。]]
.."\n\n"..xs_lbl("s_res_e_5")
.."\n\n"..xs_lbl("s_res_spl_air_race_1")
.."\n\n"..[[
<b>技能熟練：</b>躲藏、聆聽、易容、收集資訊檢定有+2種族加值。

<b>類法術能力：</b>可施展<t=@pwr_sp_litn c=fc_b>閃電束</t>、<t=@pwr_sp_displacement c=fc_b>移位術</t>、<t=@pwr_sp_cats_grace c=fc_b>貓之優雅</t>，每天各一次，施法者等級等同角色等級。
]]-- <b>無需呼吸：</b>風元素裔不需呼吸即能生存，所以他們對溺死、窒息、以及可造成類似效果的傷害免疫。-- <b>No Breathing: </b>Sylphs do not need to breathe to survive, so they are immune to drowning, suffocation, and damages that can cause similar effects.
s_pc_elm_a_langs=[[
<b>初始語言：</b>通用語、風族語。
<b>額外語言：</b>水族語、矮人語、精靈語、侏儒語、半身人語、火族語、土族語。

<c=twc>風元素裔說通用語和風族語。</c>
]]
s_pc_elm_a_d=[[
風元素裔是人類與大氣系生物混血的後裔。

類似火、土和水元素裔，她們能操縱自身元素之力，從而成為強大的元素術士。

她們美麗纖細，並有竊聽天賦。
]]
s_pc_elm_a_eds={
[race_ed_dd1]=[[
作為人類和巨靈之類氣元素的後代，風元素裔極具好奇心卻又害羞靦腆。

風元素裔融入人潮、腳步輕巧，從不被誰注意到，悄悄地側耳傾聽周遭人群的聲音。她們將這種習慣稱為“傾聽流風”，對一些風元素裔而言已是呼吸般自然之舉。

風元素裔依靠靈活機智和聽風得來的情報迴避危險。
]],
[race_ed_dd2]=[[
風元素裔是人類與風巨靈之類的氣元素的後代。風元素裔雖然外表纖細柔弱，但她們瘦削的身體經常比看上去要堅韌的多。有不少風元素裔會使用一些小手段來掩蓋自己身上的遺傳特徵，使自己混跡於人類群體中時不會被發覺真實的身份。只有十分了解他們的人有時才會注意到，這些風元素裔即使是在沒有窗戶的房間裡，身邊也會隨時揚起微風。當風元素裔憤怒或情緒激動時，這種特徵會變得明顯，例如微風會變成圍繞周身的旋風，或者將附近小物件吹落在地的氣浪。許多風元素裔都會在他們蒼白的肌膚上繪製圖案複雜的蒼藍色螺旋狀紋身。而最吸引人的是他們那曲折盤旋的長髮，猶如一團活的雲霧。

風元素裔生性害羞孤僻，他們經常巧妙的透過混入人群來避免碰到自己不願見的人。儘管風元素裔通常不願將自己捲入麻煩和紛爭，但他們卻天生對於其他人有著強烈的好奇心。這使得他們經常不遺餘力的去刺探和偷聽那些他們感興趣的人（這種習慣被稱為“傾聽流風”）。對詭計花招的熱愛和天生善於擺脫困境的能力，使得風元素裔十分適合擔當盜賊、小偷、間諜一類的角色。外表的害羞與柔弱為風元素裔的精明強幹提供了完美的偽裝，使得他們能不斷的衡量對手，分析最有效的致勝之法。
]],
[race_ed_phy]=[[
風元素裔外表纖細蒼白，但她們瘦削的身體經常比看上去要堅韌。

很多風元素裔能輕易混進人類中，儘管她們體表多處漩渦狀的蒼藍胎記揭示了其元素先祖。

風元素裔還有一些不易察覺的遺傳特徵，譬如隨身揚起的微風等等。這些特徵在風元素裔情緒激烈或憤怒時會變得明顯起來，譬如令怒髮衝冠的獵獵旋風，或能將小物體從架上掃落的熱浪等。
]],
[race_ed_soc]=[[
風元素裔常有著人類雙親，並以人類的習俗被撫養長大。多數風元素裔不喜歡人類社會看待自己的異樣目光，因此在到了年紀時離家出走司空見慣。但他們很少會背離文明之邦，而是去尋找能夠不引人注目地安身（以及刺探）的城市。

偶然悄悄看到同族的風元素裔會被對方深深吸引，盡其所能地瞭解和調查對方。只有在充分地權衡利弊、並對各種反應都做好應對預案後，風元素裔才會主動現身於他人面前。

當兩個風元素裔少有地邂逅在某個社群中時，接下去往往是一系列貓鼠追逐的遊戲，伴隨著彼此試探的閃轉騰挪和迴旋舞蹈、以求佔據上風。以這種方式相遇的風元素裔通常後來會如膠似漆或不共戴天。
]],
[race_ed_rel]=[[
風元素裔以觀察其他種族為樂，但不大願意接觸其中大多數。

出於共同的疏離感，風元素裔可以和精靈建立某種程度的聯絡，不過經常由於敏感的精靈覺得隱私被侵犯而使關係破裂。

矮人很不信任風元素裔，覺得她們輕浮而不可靠。

她們和半身人倒是至交好友，感服於這些小傢伙的勇氣、以及揚長避短的多彩技巧。

風元素裔覺得喜怒無常的火元素裔太煩人，而沉悶的土元素裔則過於無趣。
]],
[race_ed_aln]=[[
風元素裔不把律法和傳統當回事，這些東西往往禁止她們最大的愛好——迴避社會和偷偷摸摸。這並不意味著風元素裔站在法律對立面，她們只不過用最為可行的權宜之計、來達到自己合法或非法的目標而已。因此多數風元素裔是中立陣營的。

風元素天性易被秘聞吸引，以及專注於秘密、旅行和知識的神祇。
]],
[race_ed_adv]=[[
打破沙鍋問到底的天性驅使很多風元素裔踏上冒險之旅。

追尋著秘跡的風元素裔在尋獲每一條證據、走遍每一個角落、解決每一件麻煩之前是不會滿足的。

這些風元素裔也因插足他人事務而為自己樹敵不少，並常用自己的盜賊天賦或魔法技巧來保護自己。
]],
[race_ed_nam]=[[
<c=twa>常見男名：</c>
阿卡什（Akaash），艾丹（Eydan），哈努恩（Hanuun），西瓦爾（Siival），瓦薩姆（Vasaam）。

<c=twa>常見女名：</c>
伊娜穆（Inam），姬雅（Keeya），莉希（Lissi），娜娃（Nava），拉達雅（Radaya），忒娜（Tena）。
]],
}--【譯註：秘密之神－諾格巴（Norgorber，中立邪惡）；旅行女神－黛絲娜（Desna，混亂善良）；知識之神－義洛理（Irori，秩序中立）。整體上相當平衡嗯。】


s_pc_elm_f="火元素裔"
s_pc_elm_f_c="這個有著火焰般面板的健壯男子，頭髮尤如飄動的赤炎，前額上長著斑駁的雙角。"
s_pc_elm_f_fav_cls="常因縱火而被城市驅逐，火元素裔中常出強力的火術士，以及與其他種族迥異的能夠操縱火焰的戰士。"
s_pc_elm_f_traits=[[
<b c=tg>+2敏捷，+2魅力，<c=tr>-2感知：</c></b>火元素裔迅捷而又充滿熱情，但同時也很魯莽並且帶有破壞慾。]]
.."\n\n"..xs_lbl("s_res_f_5")
.."\n\n"..xs_lbl("s_res_spl_fire_race_1")
.."\n\n"..[[
<b>技能熟練：</b>跳躍、翻滾、威嚇、唬騙檢定有+2種族加值。

<b>類法術能力：</b>可施展<t=@pwr_sp_burning_hands c=fc_b>燃燒之手</t>、<t=@pwr_sp_fire_ball c=fc_b>火球術</t>、<t=@pwr_sp_rage2 c=fc_b>狂暴術</t>，每天各一次，施法者等級等同角色等級。
]]--控火術（Sp）：火元素裔可每日一次在周圍10尺內產生1道非魔法火焰，亮度從煤燃燒的昏暗火光到如同日光的白亮，照明半徑加倍，這種能力不會產生熱量，也不需要火源，可維持5分鐘，如同等5級術士施展。
s_pc_elm_f_langs=[[
<b>初始語言：</b>通用語、火族語。
<b>額外語言：</b>水族語、風族語、矮人語、精靈語、侏儒語、半身人語、土族語。

<c=twc>火元素裔說通用語和火族語。</c>
]]
s_pc_elm_f_d=[[
火元素裔是凡人與火位面奇妙生物的後代。

他們的體貌特徵和性格個性往往令其激烈血緣得以彰顯，他們無情、獨立而又狂妄。

常因縱火而被城市驅逐，火元素裔中常出強力的火術士，以及與其他種族迥異的能夠操縱火焰的戰士。
]]
s_pc_elm_f_eds={
[race_ed_dd1]=[[
火元素裔是以火巨靈等元素之火為先祖的人類，是富於激情和喜怒無常的種族。

沒有火元素裔會安於一成不變的生活；他們如同野火般必須時刻浮動、並燃燒殆盡。火元素裔不僅愛慕熾焰，他們的人格本來就是火焰的化身：激烈燃燒，變幻無常，不知憐憫。
]],
[race_ed_dd2]=[[
火元素裔是以元素之火（例如火巨靈）為祖先的人類。火元素裔都長著一對尖耳朵，額頭上有著紅色或斑點的雙角，頭髮如火焰般飄動。

所有的火元素裔幾乎都有著縱火狂的潛質，他們崇拜任何形式的火焰。他們往往性格衝動，行事魯莽，傾向於在任何衝突中都先發制人——這樣的特點使他們往往能夠得以生存卻很難交到朋友。在冒險的時候。火元素裔一般會去找那種比較軟弱，可以透過威嚇對其進行指揮的隨從，或者那種對他人比較疏遠，容易抵消火元素裔衝動天性的夥伴。
]],
[race_ed_phy]=[[
火元素裔的外貌根據先祖不同而變化多端。多數有尖耳朵，紅色或斑駁的角，頭髮如同火焰般飄動。有些人的膚色如同精煉黃銅，或者四肢覆蓋著焦炭般的鱗片。

火元素裔喜歡暴露和浮誇的紅、橙等暖色調服飾，再用俗豔的首飾加以裝點。
]],
[race_ed_soc]=[[
火元素裔多出生在人類社群中，並很少結成自己的社群。

在城市長大的火元素裔幾乎都在成年前被監禁或放逐；他們中的多數由於頭腦發熱或太過特立獨行而無法融入文明社會，縱火狂的嗜好也使他們不受當局待見。

在遊牧或部落社會出生的火元素裔要好得多，因為他們探索和征服周遭的本能可以為自己輕易地贏取領導者的地位。
]],
[race_ed_rel]=[[
即便天性最純良的火元素裔也不免將他人視為工具，因此他們與那些可以魅惑、或可以威壓的種族相處得最好。

半精靈和侏儒時常發現自己置身於火元素裔的陰謀中，而半身人、半獸人和矮人則常對火元素裔的支配天性感到慍怒。

意外的是火元素裔有時會和精靈建立格外親密的羈絆，精靈疏遠他人的天性似乎抵消了火元素裔的衝動本質。

多數火元素裔拒絕接觸風元素裔，不過倒是和其他元素裔種族相安無事。
]],
[race_ed_aln]=[[
火元素裔是性格分明之人——激烈，獨立，傲慢而又難伺候。他們經常因道德缺陷而受到指控，但他們的搗蛋天性很少出於真正惡意的動機。火元素裔通常是秩序中立或混亂中立陣營，也有少數絕對中立。

多數火元素裔缺少遵從神祇教誨的心態，也討厭受到宗教組織的束縛。當火元素裔真心崇拜神祇之時（通常是與火相關的），他們會展現出狂熱教徒和虔誠信眾的一面。
]],
[race_ed_adv]=[[
火元素裔會為追求刺激和測試抗敵技巧而踏上冒險之道，但絕大多數情況下是為追逐力量而冒險。

當火元素裔專注於某項任務時，他們無畏地進取，絕不停步思量前路有多危險。當終於因莽撞而涉險之時，火元素裔常依靠術士或吟遊詩人的魔法來擊退麻煩。
]],
[race_ed_nam]=[[
<c=twa>常見男名：</c>
阿甲（Aja），德納特（Denat），艾菲特（Efit），厄郎（Elum），亞力（Jalij），馬切（Maqej），烏拉（Urah）。

<c=twa>常見女名：</c>
阿拉伊（Alayi），艾特娃（Etwa），瑪刊（Maqan），卡莉（Qari），薩米（Sami），澤塔雅（Zetaya）。
]],
}


s_pc_elm_w="水元素裔"
s_pc_elm_w_c="這個藍膚藍髮的男人舉止優雅，他長著魚鰭狀的雙耳和帶蹼的手足。"
s_pc_elm_w_fav_cls="水元素裔對水的親和讓她們能夠成為特別優秀的德魯伊。"
s_pc_elm_w_traits=[[
<b c=tg>+2敏捷，+2感知，<c=tr>-2力量：</c></b>水元素裔兼具著敏捷以及感知力，但是她們往往選擇順應潮流而非以力較力。]]
.."\n\n"..xs_lbl("s_res_c_5")
.."\n\n"..xs_lbl("s_res_spl_water_race_1")
.."\n\n"..[[
<b>技能熟練：</b>游泳、估價、醫療、交涉檢定有+2種族加值。

<b>類法術能力：</b>可施展<t=@pwr_sp_heal c=fc_b>治療術</t>、<t=@pwr_sp_bless c=fc_b>祝福術</t>、<t=@pwr_sp_aid c=fc_b>援助術</t>，每天各一次，施法者等級等同角色等級。
]]
s_pc_elm_w_langs=[[
<b>初始語言：</b>通用語、水族語。
<b>額外語言：</b>風族語、矮人語、精靈語、侏儒語、半身人語、火族語、土族語。

<c=twc>水元素裔說通用語和水族語。</c>
]]
s_pc_elm_w_d=[[
水元素裔和她們的土、風、火族表親相似，是人類與元素位面的混血後代。

她們則是水元素的末裔，在陸上和水中同樣優雅得體。

水元素裔適應並能抵禦寒冷，同時對水系魔法親和性甚高。
]]
s_pc_elm_w_eds={
[race_ed_dd1]=[[
水元素裔是可將祖先溯至水位面生物的人類。水元素裔的每一塊肌膚都是湖泊、海洋的擬似，即便一眼就能看出她們的先祖血脈。無論親族是水靈或海妖，所有的水元素裔按先祖出身來自我區分。她們將個體差異當作天賦賜予，並探索著自己特殊血脈的超自然昇華。

水元素裔是面無懼色的驕傲種族。天性善良的她們在與同族相處時愛開玩笑，而和外族打交道時相對要保守和嚴肅一些。她們情緒自控的能力極為出色，能夠在瞬息之間讓心態在冷靜與狂暴的邊緣自如遊走。有些人可能會覺得她們喜怒無常，其實水元素裔只是感情相較他族稍微誇張了一點而已。她們當然不是神經病，不會無緣無故地陷入憤慨、興奮或是其他情緒中。水元素裔的親密友人有時會發現她們佔有慾過強，不過她們對於珍視之人確實有著強烈的保護欲。

水元素裔通常在溫暖氣候下臨水而居。雖然生活在陸地上，她們喜歡在水裡待很長時間。多數水元素裔出於這個理由穿得很少，通常只穿戴足以防護嚴酷氣候的服裝，並多赤足。她們儘量避免在頸部佩戴首飾，並將頭髮盤紮成結。她們會防止頭髮或其他物件在游泳時成為妨礙。類似地，習練武技的水元素裔也會選擇那些在陸上、水中同樣順手的兵器。
]],
[race_ed_dd2]=[[
水元素裔是可將祖先溯至水元素相關生物（如水巨靈）的人類。

這種與水元素位面的深刻聯絡，透過水元素裔猶如混合了湖泊與海洋的膚色，可以很明顯的看出他們與水元素位面的聯絡——水元素裔都有著清澈的藍色眼睛，他們的面板和頭髮顏色多變，從蒼青到深藍、再到水綠。
]],
[race_ed_phy]=[[
水元素裔的膚色變化多端，從蒼青到深藍、再到水綠。水元素裔濃密的直髮顏色會和膚色接近，但比膚色更深一些。她們全都有著清澈的藍眼睛。

水元素裔生理上而言最接近人類，因此身高體型也如同人類般彼此迥異。

除了膚色，她們最大的種族特徵就是魚鰭狀的耳朵和有蹼的手足。
]],
[race_ed_soc]=[[
水元素裔自視為獨一無二的種族，並能夠相互繁衍。雖然能和人類誕下後代，她們還是傾向於種內婚配，並在水源附近組成小小的隱居社群、或遊牧於水畔。水元素裔社群內部的通婚很普遍，並共同撫養小孩。

典型的水元素裔社群在小評議會的指導下生活，並在公共事務上尋求意見一致。評議會可以長久地存續，不過當社群對其某位成員的表現不滿時可以彈劾其下臺。

水元素裔文化的宗教多樣性相當大，這也是不同集落之間先祖出身各異的結果之一。值得一提的是，同一個集落裡的水元素裔也未必有著共同祖先，而她們也可能和來自其他社群的水元素裔結姻。
]],
[race_ed_rel]=[[
水元素裔對任何種族都不抱有偏愛或歧視。她們的社群依賴於商貿，這給予她們和廣泛的外族相互接觸的機會。她們也不介意在其他種族的集落裡定居，只要對方能夠同等地尊重水元素裔和鄰近的水域。即便這種情況下，一個水元素裔社群還是會盡量保持自主權。

水元素裔與精靈和侏儒的關係格外融洽，這些種族往往身為森林中湖泊和溪流的守護者。類似地，她們也樂於同善良或中立水生類人生物打交道，因為彼此有著共同的偏好。她們會和人類以及矮人交易鋼鐵和布料等資源。
]],
[race_ed_aln]=[[
多數水元素裔是中立的。她們的原則在於維護同族人民的福祉，因此道德規範也常專注於社群整體。這種中立的視角也讓她們能和廣泛的外族之間展開貿易來往。

儘管並無宗教狂熱，水元素裔和超自然祖先以及“水”本身之間都有著強烈的精神聯結。那些追求超脫凡俗之道的水元素裔幾乎全都會崇拜自己先祖的神祇，或是神職、權能中和水有關的神祇。
]],
[race_ed_adv]=[[
某些時候，水元素裔會離開族人、踏上冒險之旅。如同水一般，很多水元素裔只是單純地喜歡流動，而冒險給予了她們最合適不過的旅行藉口。

有些人的冒險理由沒有如此光彩，譬如因為在社群內犯下的罪行而遭流放。沒有更多選擇的被放逐者只能冒險和遊蕩，期盼著能為自己找到新的家園。

水元素裔對水的親和讓她們能夠成為特別優秀的德魯伊，而水元素裔術士則多為深洋血統。
]],-- 深洋血統（Aquatic, APG）
[race_ed_nam]=[[
<c=twa>常見男名：</c>
阿溫（Aven），達拉克（Dharak），基輔（Ghiv），雅瑪士（Jamash），馬考（Maakor），翁狄爾（Ondir），拉迪（Radid），西拉達茲（Shiradahz）。

<c=twa>常見女名：</c>
阿芙珈拉（Afzara），芭拉（Baarah），卡拉（Calah），伊莉亞妮（Iryani），瑪琳（Maarin），妮讓（Nylgune），帕芮（Pari），拉達蓓（Radabeh），厄妲娜（Urdahna）。
]],
}


s_pc_elm_e="土元素裔"
s_pc_elm_e_c="這個高大的戰士沉穩而堅定，如鑿刻般稜角分明的面孔使她看起來就像一個有了生命的雕像。"
s_pc_elm_e_fav_cls="由於天生擁有強壯身軀和自律精神，土元素裔是優秀的武僧和戰士。"
s_pc_elm_e_traits=[[
<b c=tg>+2力量，+2感知，<c=tr>-2魅力：</c></b>土元素裔強壯，可靠，沉穩並且恬淡寡欲。]]
.."\n\n"..xs_lbl("s_res_a_5")
.."\n\n"..xs_lbl("s_res_spl_earth_race_1")
.."\n\n"..[[
<b>技能熟練：</b>攀爬、偵察、生存、專注檢定有+2種族加值。

<b>類法術能力：</b>可施展<t=@pwr_sp_shield_other c=fc_b>護衛他人</t>、<t=@pwr_sp_stoneskin c=fc_b>石膚術</t>、<t=@pwr_sp_bears_endurance c=fc_b>熊之堅韌</t>，每天各一次，施法者等級等同角色等級。
]]
s_pc_elm_e_langs=[[
<b>初始語言：</b>通用語、土族語。
<b>額外語言：</b>水族語、風族語、矮人語、精靈語、侏儒語、半身人語、火族語、地底通用語。

<c=twc>土元素裔說通用語和土族語。</c>
]]
s_pc_elm_e_d=[[
土元素裔的祖先是混有土元素位面血統的人類，他們同磐石一樣強固。

經常頑固而又堅定，他們不屈的天性令自己很難與矮人以外的大多種族友好相處。

土元素裔能成為優異的武士或術士，能夠操控大地與后土的原生之力。
]]
s_pc_elm_e_eds={
[race_ed_dd1]=[[
土元素裔是祖先曾與大地元素（經常是土巨靈）有過接觸的人類後裔。

堅忍克己、愛好冥思，土元素裔是不易動搖的種族，在行動時卻又不可阻擋。由於出世的天性，他們對多數世人而言仍是神秘的存在；但那些在與世隔絕的世外桃源找到土元素裔的旅者，會發現他們是沉穩、可靠、保護性強的朋友。
]],
[race_ed_dd2]=[[
土元素裔是祖先曾與大地元素（經常是土巨靈）有過接觸的人類後裔。土元素裔體格強壯堅實，通常他們偏好於穿著和大地色調一致的衣物，這可以搭配他們那特殊的膚色和髮色（通常是如石斑一樣的灰、棕、黑或白色）。少數情況下，有的土元素裔元素血脈的特徵會表現的極其明顯，他們的面板和頭髮會長出礦石晶簇，讓旁人一眼就能認出他們的來歷。

土元素裔性情沉穩內斂，他們很少動怒，但在戰鬥中依然十分可怕。在團隊中，他們傾向於擔當安靜、可靠、為大家提供保護的角色。
]],
[race_ed_phy]=[[
土元素裔強壯而又堅固，面板和毛髮都呈黑、褐、棕、灰或白等石斑的顏色。

儘管所有土元素裔的外表樸實厚重，少數特徵還是體現了他們的元素遺傳——瑪瑙般的面板，磐石般虯結的塊狀肌肉，寶石般閃耀的雙眼，水晶叢般的頭髮……等等。

他們衣著簡樸，穿著適於活動的衣服並用鮮花、純色寶石、以及其它從天然到手工的精緻小物件加以裝點。
]],
[race_ed_soc]=[[
作為人類的小小分支，土元素裔並沒有自己的社會組織。多數土元素裔都在人類社群中長大成人，從父母處學習風土人情。

成年的土元素裔相較其他種族而言，有著強烈的避世隱居的傾向。少有土元素裔能適應喧囂的都市生活，他們更願意在人跡罕至的萬仞峰頂、絕世獨立的的理想鄉中靜思度日。

與人類親近的土元素裔經常會加入城市守衛隊，或尋找其他能夠以責任感為社群效命的崗位。
]],
[race_ed_rel]=[[
土元素裔與矮人關係很好，因為兩者共性甚多。

他們覺得侏儒太過怪異、半身人自以為是，大體上避免和他們接觸。

土元素裔高興和半獸人、半精靈交往，儘管有著不可避免的人格衝突，畢竟可以在彼此之間同有的人類血脈中找到羈絆。

土元素裔和其他元素裔種族並無深交，也非仇敵。
]],
[race_ed_aln]=[[
土元素裔可能是最為頑固的種族，一旦確定路線，將會靜靜地拒絕任何打擾。

土元素裔會奮不顧身地保護朋友們，但不太在乎熟人之外的世間善惡。因此多數土元素裔秩序中立。

這些大地之靈易受宗教感召。他們喜歡隱修教會安靜、避世的生活，並大多崇拜那些土系、或與自然相關的神祇。
]],
[race_ed_adv]=[[
土元素裔一開始是猶豫不決的冒險者。他們不喜歡離鄉背井，也不太善於處理各種新體驗。往往是有外力迫使土元素裔展開行動，譬如威脅他們的故鄉、生命或是朋友等。當最初遭受的威脅解除時，土元素裔常會發現自己已經習慣了冒險生活，並會在這條道路上奉獻餘生。

由於天生擁有強壯身軀和自律精神，土元素裔是優秀的武僧和戰士。
]],
[race_ed_nam]=[[
<c=twa>常見男名：</c>
安達南（Andanan），吉達烏（Jeydavu），蒙提斯（Mentys），歐列特（Oret），西桑丹（Sithundan），爾塔（Urtar）。

<c=twa>常見女名：</c>
貝薩娜（Besthana），愛莎涅（Echane），迦提亞拉（Ghatiyara），伊利瑟（Irice），奈瑟涅（Nysene），帕謝（Pashe）。
]],
}-- 視既感（Jeydavu）


s_heat="高溫"
s_heat_d="火矮人的身體非常熾熱，因此他們的徒手攻擊會造成額外的火焰傷害。他們的金屬武器也會傳導這種高溫。"

s_azer="火矮人"
s_azer_c="高熱扭曲了這個矮胖的黃銅色面板的人型生物周圍的空氣。他的頭部和肩部都閃耀著一串火焰。"
s_azer_fav_cls="火矮人可以把高溫傳導到金屬武器或工具上，所以他們幾乎不使用非金屬武器，並且通常在戰鬥中傾向於近戰而非遠端攻擊。"
s_azer_traits=[[
<b c=tg>+2力量，+2敏捷，+2體質，+2智力，+2感知，<c=tr>-2魅力：</c></b>除了不太友善而且沉默寡言，火矮人在各方面都表現不俗。

<b>種族生命骰：</b>火矮人初始擁有2個異界生物等級，給予它2d8生命骰。

<b>種族技能：</b>火矮人的異界生物等級給予它5 x (8 + 智力調整值)的技能點數。其本職技能為攀爬、跳躍、躲藏、估價、手藝、搜尋、偵察、聆聽。

<b>種族專長：</b>火矮人的異界生物等級給予它1個專長。

<b>防禦：</b>+6天生防禦加值。

<b>武器和盔甲擅長：</b>擅長簡易武器、戰錘、輕甲、中甲、盾牌。

<b>特殊能力：</b><t=@pwr_heat c=fc_b>高溫</t>，<t=@pwr_imm_f c=fc_b>火焰免疫</t>，<t=@pwr_vul_c c=fc_b>寒冷易傷</t>，<t=@pwr_spl_res_13 c=fc_b>法術抗力13+</t>。
]]-- +2的基本攻擊加值，以及強韌+3、反射+3和意志+3的基本豁免加值。a base attack bonus of +2, and base saving throw bonuses of Fort +3, Ref +3, and Will +3.
s_azer_langs=[[
<b>初始語言：</b>通用語、火族語。
<b>額外語言：</b>深淵語、水族語、風族語、天界語、煉獄語、土族語。

<c=twc>火矮人說火族語和通用語。</c>
]]
s_azer_d=[[
火矮人是出生於火元素位面的類矮人生物。他們穿著由黃銅、青銅或赤銅打造成的短裙，並且說火族語和通用語。火矮人在不熟悉的人眼中看起來都差不多。它們有4尺高，但是重200磅。

火矮人生活在一個所有人都恪盡職守的社會中。它們在青銅或黃銅要塞中辛勤勞作，為了即將爆發的和火巨靈之間的漫長戰爭而時刻準備著。

傳奇的黃銅之城據火矮人自稱有超過五十萬人口。大多數不幸的火矮人作為它們火巨靈主人的奴隸而生活。

除了黃銅之城，其他火矮人們自由地生活著，經常在異界的大城市中製造工藝品、做買賣或開酒館。
]]-- 火矮人是火元素位面上驕傲而勤勞的種族	A proud and hardworking race from the Plane of Fire
s_azer_eds={
[race_ed_dd1]=[[
]],
[race_ed_dd2]=[[
]],
[race_ed_dd3]=[[
]],
[race_ed_dd4]=[[
]],
[race_ed_phy]=[[
]],
[race_ed_btl]=[[
火矮人在戰鬥中使用平頭矛或者製作精良的戰錘。在空手時，他們會試圖擒抱對手。

火矮人可以把高溫傳導到金屬武器或工具上，所以他們幾乎不使用非金屬武器，並且通常在戰鬥中傾向於近戰而非遠端攻擊。

儘管不太友善而且沉默寡言，但是火矮人很少挑起爭鬥，除非對方帶著他們所喜愛的寶石。

如果受到了威脅，那麼火矮人會奮戰到底，但是他們瞭解俘虜敵人所帶來的價值。火矮人經常抓獲俘虜，然後把它們帶回要塞中，強迫它們長年累月地勞動。
]],
[race_ed_soc]=[[
火矮人生活在一個所有人都恪盡職守的社會中。火矮人生來就被賦予特定的角色，通常繼承自它們父母，而他終其一生都必須履行他的職責。

種姓制度讓火矮人的社會秩序更加牢固。貴族的統治毫無疑議，穿著者象徵著它們種姓的黃銅裝飾的短裙，而商人和資本家則穿著厚實的青銅，工人階級則被指定穿著紅銅，他們主要是僕人、工匠和勞動者。

傳奇的黃銅之城據火矮人自稱有超過五十萬人口。大多數不幸的火矮人作為它們火巨靈主人的奴隸而生活。

火矮人就算被當做奴隸也毫無疑問地履行著它們的職責，寧願等到契約結束或它們的主人死掉或被推翻之時。對秩序的奉獻深深地烙印在這個種族上，已經達到了一些火矮人奴隸能被選出作為監工來看管其他同胞的程度。

除了黃銅之城，其他火矮人們自由地生活著，經常在異界的大城市中製造工藝品、做買賣或開酒館。
]],
[race_ed_rel]=[[
]],
[race_ed_aln]=[[
]],
[race_ed_adv]=[[
]],
[race_ed_nam]=[[
]],
}

s_genie			="巨靈"
s_genie_d		=[[巨靈是居住在元素位面的長得像人類的生物。它們素以其強壯，狡詐及善用幻術而聞名。

巨靈喜歡以策略和計謀戰勝敵人。如果逃跑會使它們活下來他日再戰的話，它們也不會寧死不屈。如果被困住，它們會提出給予寶物或提供某種回報來換取其生命和自由。]]

-- 元素		Elemental
