s_elm_a2		="風元素"	s_elm_a2_d=[[風元素會說風族語，但是它們很少開口。

<b c=tw>戰鬥</b>
風元素極快的速度使得它們在遼闊的戰場或長時間空戰中獲得巨大的優勢。

<b c=tw>風元素體型</b>
<b c=tw>元素	高度	重量</b>
小型	4尺	1磅
中型	8尺	2磅
大型	16尺	4磅
超大型	32尺	8磅
巨型	36尺	10磅
長老	40尺	12磅]]

s_elm_e2		="土元素"	s_elm_e2_d=[[被召喚到物質界時，土元素由各種不同型別的泥土，石頭，貴金屬和寶石組成。

土元素會說土族語，但是它們很少開口。

<b c=tw>戰鬥</b>
儘管土元素移動緩慢，但它是無情的對手。它能在堅固的地表和岩石中行走，就好像人類在地面行走一樣容易。它不會游泳，如果遇到水域時，只能繞過去或者從水下的土地中穿越。土元素可以在水底移動但是它們不喜歡那麼做。

<b c=tw>土元素體型</b>
<b c=tw>元素	高度	重量</b>
小型	4尺	80磅
中型	8尺	750磅
大型	16尺	6000磅
超大型	32尺	48000磅
巨型	36尺	54000磅
長老	40尺	60000磅]]

s_elm_f2		="火元素"	s_elm_f2_d=[[火元素無法進入水或任何不可燃的液體之中。任何水域對火元素來說都是不可跨越的障礙，除非它們能跨越或跳躍過去。

火元素會說火族語，但是它們很少開口。

<b c=tw>戰鬥</b>
火元素是個兇猛的對手，它會直接而野蠻地攻擊它的敵人。將物質界的生物和物品燒成灰燼是它的樂趣。

<b c=tw>火元素體型</b>
<b c=tw>元素	高度	重量	燒灼DC</b>
小型	4尺	1磅	11
中型	8尺	2磅	14
大型	16尺	4磅	17
超大型	32尺	8磅	22
巨型	36尺	10磅	24
長老	40尺	12磅	26]]

s_elm_w2		="水元素"	s_elm_w2_d=[[水元素與形成它們的水域之間的距離不能超過180尺。

水元素會說水族語，但是它們很少開口。

<b c=tw>戰鬥</b>
水元素喜歡在大面積的水域中作戰，這樣它就可以在波浪後面消失並出其不意地出現在其對手身後。

<b c=tw>水元素體型</b>
<b c=tw>元素	高度	重量</b>
小型	4尺	34磅
中型	8尺	280磅
大型	16尺	2250磅
超大型	32尺	18000磅
巨型	36尺	21000磅
長老	40尺	24000磅]]

s_air_mastery	="天空熟悉"	s_air_mastery_d		="飛行中的生物在對抗風元素時其攻擊和傷害檢定上會受到-1的罰值。"
s_earth_mastery	="大地熟悉"	s_earth_mastery_d	="當土元素和它的敵人都能接觸地表時，它在攻擊和傷害檢定上可獲得+1的加值。如果對手在空中或者水裡，則土元素在上述檢定上會受到-4的罰值。"-- （列表中未包含上述資料。）
s_water_mastery	="水域熟悉"	s_water_mastery_d	="當水元素和它的對手都能接觸到水時，它在攻擊和傷害檢定上可獲得+1的加值。如果水元素或其對手在陸地上，則水元素在上述檢定上會受到-4的罰值。\n\n水元素對穿越其行進路線的船隻會造成嚴重的威脅。水元素可以輕易地翻轉小型船隻（水元素每生命骰相當於船隻5尺長度）並讓較大型船隻停駛（水元素每生命骰相當於船隻10尺長度）。即使大型船隻（水元素每生命骰相當於船隻20尺長度）也會被減慢到一半的速度。"-- （列表中未包含上述資料。）
s_earth_push	="推進"		s_earth_push_d		="土元素展開衝撞動作時不會引發藉機攻擊。大地熟悉提供的戰鬥調整值在土元素進行戰技檢定時也適用。"-- 力量檢定 opposed Strength
s_earth_glide	="遁地"		s_earth_glide_d		="土元素可以如魚在水中游泳一樣在石頭，泥土或除了金屬之外任何型別的土地內部穿行。它掘穴時不會在身後留下任何隧道或洞穴，也不會產生細微震動或任何表明它的存在的跡象。"-- 施展在正在掘穴中的土元素所在區域上的移土術會將它向後丟擲30尺，除非成功透過一個DC15的強韌豁免檢定它還會被震懾1輪。 A move earth spell cast on an area containing a burrowing earth elemental flings the elemental back 30 feet, stunning the creature for 1 round unless it succeeds on a DC 15 Fortitude save.
s_fire_burn		="燒灼"		s_fire_burn_d		="火元素的揮擊攻擊能製造出鈍擊傷害外加燃燒的身體所帶來的火焰傷害。被火元素的揮擊攻擊擊中的對手必須要透過一個反射豁免檢定（DC = 10 + 火元素HD/2 + 體質調整值）否則身上就會著火燃燒1d4輪。著火的生物可以透過一個移動動作來撲滅火焰。\n\n使用其天生武器或者徒手攻擊命中火元素的生物會如被火元素擊中一樣受到火焰傷害，而且它們必須透過反射豁免檢定否則也會渾身著火。"-- 而異 (見下表) (see the table below)
s_water_drench	="浸溼"		s_water_drench_d	="水元素的觸控可以熄滅火把，螢火，暴露在外的燈火，以及其他大型或更小的非魔法且無保護的火焰。水元素可以透過觸控解除魔法火焰，如同解除魔法法術一樣（施法等級等於水元素生命骰）。"
s_water_skls	="技能"		s_water_skls_d		="在進行遊泳檢定來做出特殊動作或躲避危險時水元素可獲得+8的種族加值。它可在游泳檢定中總是取10，即使注意力被分散或處於危險時也一樣。它可在游泳中使用奔跑動作，但是隻能直線前進。"
s_air_whirlwind	="旋風"		s_air_whirlwind_d	=""
s_water_vortex	="旋渦"		s_water_vortex_d	=""

-- 異怪		Aberration
s_naga			="納迦"
s_naga_d		=[[所有納迦都擁有細長的、被閃爍的鱗片所覆蓋的蛇形身體，以及多少有些類似於人類的面孔。它們身長在10到20尺之間，體重在200到500磅之間。納迦的眼睛明亮慧詰，燃燒著一種幾乎可將人催眠的心靈之光。

納迦偏愛法術勝於其他型別的戰鬥。因為它們總是在其守衛且熟知的巢穴中出現，所以它們可以按自己的意願來安排大多數的遭遇。]]

-- 龍		Dragon
s_true_dragon	="真龍"
s_true_dragon_d	=[[真龍（而非其他屬於龍類的生物）的已知種類可粗分為兩個類別：五色龍及金屬龍。

五色龍包括黑龍、藍龍、綠龍、紅龍及白龍，它們全都非常邪惡且極為兇狠。

金屬龍則有黃銅龍、青銅龍、赤銅龍、金龍及銀龍，它們都屬於善良陣營，而且通常都很高貴，受到智者的高度尊崇。

所有龍都會隨著年齡增長而獲得更多的能力與更強的力量（其他屬於龍類的生物並不會如此）。龍剛孵化時身長只有數英尺，而當它們成長到太古龍時可超過100英尺長。不同種類的龍體型準確的大小會根據年齡和種類有所不同。

所有龍都說龍語。]]
s_true_dragon_e	=[[一條龍的消化系統就像一個極高效的熔爐，甚至連無機物也能消化。有些龍還對無機物有特殊的口味。

雖然龍的目標及想法會因種類而有極大差異，但它們都十分貪婪。它們喜歡收藏財寶，收整合堆的錢幣，並儘可能收集寶石、珠寶及魔法物品。那些擁有大批收藏品的龍不願意離開這些寶藏太長時間，只有在巡視附近區域或找尋食物時才會離開巢穴。對於龍來說，財寶永遠都不會足夠。這些寶藏是如此賞心悅目，龍喜歡沉浸在寶藏的光輝之中。龍喜好用它們的寶藏作床鋪，在上面弄出一個適合自己體型的隱蔽處。當龍成長到太古龍階段時，它的面板上將會因此鑲嵌上數百枚寶石。]]

s_half_dragon	="半龍"
s_half_dragon_d	=[[半龍生物總是比其沒有龍類血脈的同族更加強壯，而且外觀上也有很大差異 - 鱗片，瘦長的體形，爬蟲類的眼睛，誇張的牙齒和爪子。有時候它們會長有翅膀。]]

-- 動物		Animal
s_rat			="鼠"
s_rat_d			=[[這些雜食性的齧齒動物幾乎可以在任何地方繁衍。遭遇戰鬥時，它們通常會選擇逃跑。齧咬僅作為它們的最後手段。]]

s_rat_x			="兇暴鼠"
s_rat_x_c		="這骯髒的老鼠體型幾乎跟小狗一樣大。它披著粗糙的皮毛，長尾巴光禿禿的，兩隻眼睛閃閃發光。"
s_rat_x_d		=[[兇暴鼠是雜食性的食腐動物，但是會為保衛巢穴和領土而展開攻擊。成群的兇暴鼠在攻擊時極為兇猛，用它們尖利的門牙齧咬並嚼碎對手。它們經常出沒於地下城和城市下水道。

兇暴鼠能長到4尺長，體重超過50磅。兇暴鼠的體型幾乎跟小狗一樣大，披著粗糙的皮毛，長尾巴光禿禿的，兩隻眼睛閃閃發光。]]

