s_dog_ride		="騎乘用犬"
s_hyena			="鬣狗"

s_wolf			="狼"
s_wolf_c		="這隻強大的犬科動物有一雙銳利的黃色眼珠，在它鋒利的白牙之間伸出一條舌頭。"
s_wolf_d		=[[狼是以固執和狡猾而著稱的群居獵食者。狼單獨或成群結隊地行動，它們位於食物鏈頂端。它們具有兇猛的領土意識和異常廣闊的狩獵範圍，狼群散佈在廣大的區域中。

狼寬闊的腳爪上，腳趾之間含有輕巧的肉墊，能夠讓它們在雪地裡移動，它們的皮毛很厚且防水，顏色從灰色到棕色，甚至有些種類是黑色。它們的爪子上包含嗅覺腺體，會在所有它們到過的地方留下記號，可以讓狼群的其他成員知道它的下落。

一般來說，狼站立的時候肩高2.5至3尺，重量在45至150磅之間，雌性則略小。

它們最喜歡的戰術是讓幾隻單獨的狼從正面攻擊敵人，同時其他的狼繞個圈從敵人的後方進行夾擊。]]

s_wolf_x		="兇暴狼"
s_wolf_x_c		="這隻巨大的黑狼體型跟一匹馬一樣大，尖牙像匕首一樣大和鋒利。"
s_wolf_x_d		=[[兇暴狼是普通狼的巨大化版本，它代表了狼最原始的形態。這些生物的基本行為和普通的狼一樣，但是更加具有攻擊性。兇暴狼喜歡成群地攻擊，儘可能包圍和夾擊對手。兇暴狼是群會殺死它們所能抓到的任何生物的高效獵人。

兇暴狼經常為巨人當做打獵的夥伴或兇猛的看門動物。一些兇殘的人型生物和樵夫訓練兇暴狼作為坐騎。

兇暴狼的毛色比一般的狼更深，趨向於黑色和斑駁的深灰色。成年兇暴狼一般大約9尺高，重量約800磅，體型跟馬一樣大，尖牙像匕首一樣長和鋒利。]]-- 兇暴狼的皮毛是斑駁的灰色與黑色，約9尺長，重約800磅。

