s_dire_animal	="兇暴動物"
s_dire_animal_d	=[[兇暴動物是一般動物的更大、更難纏、更好鬥的版本。它們通常具有兇殘的、史前的、甚至惡魔般的外貌。]]

s_dinosaur		="恐龍"
s_dinosaur_d	=[[恐龍的狀貌體型各異。較大的恐龍通常呈土褐色，而較小的膚色更具變化性。多數恐龍面板都紋理粗糙。

恐龍在戰鬥中會充分發揮速度和體型的優勢。這些行動迅捷的食肉動物會跟蹤獵物，隱藏自己的身形直到接近目標後發動衝鋒攻擊。草食性恐龍通常會衝撞並跺踏目標。]]

-- 魔法獸	Magical Beast
s_basilisk		="石化蜥蜴"
s_basilisk_c	="這隻矮胖的爬蟲類怪物有八條腿，背後突出許多骨刺，眼睛放射出灼熱的淺綠色光芒。"
s_basilisk_d	=[[石化蜥蜴是一種爬行類怪物，活著的生物只要被它凝視一眼就會變成石頭。

石化蜥蜴通常有著暗棕色的身體和黃色的下腹部。某些品種的鼻子上還會長出一根短而彎的角。成年石化蜥蜴可以長到6英尺長，如果算上尾巴的話還可以再加上5到7尺的長度。這種生物重約300磅。

石化蜥蜴依賴於它的凝視攻擊，只有當對手足夠近的時候才會用齧咬攻擊。儘管它有八條腿，但是由於新陳代謝緩慢，所以它們不會把力氣花在不必要的地方。入侵者撞見石化蜥蜴時，若選擇逃跑而非戰鬥，會發現對方在追擊時有點漫不經心。

石化蜥蜴大部分時間都是在躺著等待獵物，包括小型哺乳動物，鳥類，爬蟲類以及類似的生物。]]
s_basilisk_e	=[[石化蜥蜴，經常被稱為“蛇王”，實際上它完全不是蛇類，而是擁有八條腿的爬蟲類。它有著惡劣的性格，善於用凝視把生物變成石頭。民間傳說記載，類似於雞蛇獸，第一隻石化蜥蜴是蛇下的蛋由公雞孵化所生。但是石化蜥蜴所表現出的生物特徵卻難以讓人相信這一點。

石化蜥蜴生存與任何地面環境，從森林到沙漠，並且它們喜歡隱藏於和自己相協調的環境中——一隻沙漠中居住的石化蜥蜴會是棕褐色的，而居住於森林中的石化蜥蜴則會是淺綠色。它們喜歡在巖穴、挖出的洞穴或其他可以獲得庇護的居所，而且它們的巢穴裡會裝飾著人和動物的雕像——還保持著生前的姿勢和不幸撞見石化蜥蜴時臉上錯愕驚恐的表情。

石化蜥蜴能夠以他們石化的生物為食，他們劇烈翻滾著的酸性胃液能從石頭中吸取養分，但是過程十分緩慢，這讓它們十分懶散和行動遲緩。所以，石化蜥蜴會偷偷接近以捕食那些躲過他們凝視的獵物，依靠它們的潛行和出其不意的襲擊來保證它們自己的安全和胃口都能得到滿足。它們平時以捕食小動物、小鳥和爬蟲類為食，當它們不捕食的時候，會在巢穴裡睡覺以打發時間。而那些足夠勇敢到想去捕獲石化蜥蜴或者從它們身邊偷取財寶的冒險者們會發現它們其實簡直天生的衛兵和守財奴。

一隻成年的石化蜥蜴有13尺長，它們的長尾巴就佔了一半長度，重量則達300磅。有些品種則在鼻子上長出彎曲的尖角，或者在頭頂長出骨質的角冠，就好像皇冠一般。它們一般是獨居生物，但是在交配和生蛋時會聚集在一起，在特別危險的區域裡它們會成群聚集以保護自己並攻擊來犯之敵。

由於某些不明原因，黃鼠狼和雪貂對石化蜥蜴的凝視免疫，會在石化蜥蜴的父母出去狩獵時潛入它們的巢穴中，吃光它們的幼崽。另外有傳言表示石化蜥蜴的血液能把普通石料變成別的材質，但是這有可能是目擊者看到了石化蜥蜴血液復原被石化的生物或肢體的事實，從而產生的誤解。]]

s_liz_l	="電蜥蜴"
s_liz_l_c	="這隻狗一樣大的蜥蜴長著兩隻犄角，頭兩側一邊一隻。身體的鱗片上閃爍著藍色的電火花。"-- 綠色的鱗片...
s_liz_l_d	=[[電蜥蜴身體下方呈淺灰色或藍色，至其背部逐漸變暗。它的背部和尾部上有藍黑色的斑紋。

電蜥蜴肩高約1尺，重約25磅，體型跟狗一樣大，長著兩隻犄角，頭兩側一邊一隻，身體的鱗片上閃爍著藍色的電火花。

電蜥蜴依賴其電擊能力進行戰鬥。電蜥蜴只有在其電擊使其對手昏迷或者完全無效時才會齧咬對手。單獨一隻電蜥蜴會在放出電擊之後逃走，但如果周圍有其他電蜥蜴的話，它們會夥同同伴一起給予敵人致命的電擊。]]
s_liz_l_e	=[[電蜥蜴的腹部是淡黃色的，亮綠色的鱗片覆蓋著它3尺長的身體，重量約為25磅。電蜥蜴傾向於群居，當它們彼此接近時，它們的放電能力會隨之增強。

電蜥蜴的群落通常靠近水源。一旦群落在一個地點定居，這些蜥蜴就變得非常具有領土性並且會攻擊任何入侵者。單獨的電蜥蜴是膽小而怯懦的生物——但是當數只電蜥蜴聚集的時候它們會變成強大和可怕的對手，能夠殺死幾倍於自己體形的生物。

電蜥蜴在戰鬥中依靠其放電能力進行戰鬥，並且喜歡在用電擊讓人失去意識之後，或當它們的電擊看起來毫無影響時才進行噬咬攻擊。一個單獨的電蜥蜴會在放電之後逃離戰場，但是如果附近有多隻電蜥蜴的話，它們會齊心協力向敵人射出致命的閃電。

許多人試圖捕捉和馴服電蜥蜴，但是這通常都是痛苦而困難的任務。單獨囚禁的電蜥蜴會迅速衰弱而死，除非它們花費大量的時間來和同伴們一起玩耍嬉鬧。如果馴養成對或更多數量的電蜥蜴，它們會茁壯成長，但是它們群聚在一起時的放電能力讓那些不能免疫電擊的馴養者更為頭疼。]]

-- 蟲類		Vermin
s_ant_g		="巨蟻"
s_ant_g_c	="一隻有著六條細長腿的螞蟻有一匹站著的矮種馬一般大小，它的上顎不斷開合，它的刺上不斷滴落毒液。"
s_ant_g_d	=[[巨蟻是所有蟲類生物中最堅韌，也是適應性最強的一種。

巨蟻的體型跟矮種馬差不多。巨兵蟻和巨工蟻約6尺長，巨蟻后則可長至9尺。

巨蟻跟普通體型的他們的親戚一樣勤勞。雖然他們的巢裡不是由上千螞蟻組成，但是他們獲得的體型上的好處遠遠彌補了這一點。]]

s_spider_mons	="變種蜘蛛"
s_spider_mons_c	="一隻像人那麼大的蜘蛛靜悄悄地從它漏斗型的網深處爬出。"
s_spider_mons_d	=[[所有的變種蜘蛛都是攻擊性極強的掠食者，它們使用其劇毒的齧咬來剋制或殺死獵物。

變種蜘蛛可分為兩個類別：狩獵蛛和結網蛛。狩獵蛛到處跑來跑去，結網蛛則通常嘗試用蛛網捕捉獵物。狩獵蛛能結網來做為巢穴，但不能像結網蛛一樣使用蛛網作為武器。]]

-- 植物		Plant

-- 泥形怪物	Ooze

-- 不死生物	Undead
s_skeleton		="骷髏"
s_skeleton_d	=[[骷髏是會活動的骨骸，遵循其邪惡主宰的命令而行動的沒有心智的傀儡。

除了在被殺之際所穿盔甲的腐爛碎塊外，這些不死生物很少帶著其他東西。

骷髏只執行它們接受的命令，它們沒有自主的推斷力。由於這個限制，給予他們的命令通常很簡單。

骷髏會一直戰鬥直到被摧毀。]]

s_zombie	="殭屍"
s_zombie_d	=[[殭屍是被黑暗而罪惡的法術所復活的屍體。

由於它們極度缺乏智力，所以對剛創造出來的殭屍下達命令時必須非常簡單扼要。]]

s_ghost		="幽魂"
s_ghost_d	=[[幽魂是智慧生物所遺留下來的靈體，它們因為某些理由無法輕易安息在墓穴裡。

幽魂的外貌與生前大致相同，但有些情況下其靈體外貌會有一些改變。]]

s_ghoul		="食屍鬼"
s_ghoul_c	="這個人型生物長著長而鋒銳的牙齒，它死白的皮肉緊繃繃地撐在因飢餓而拉伸的骨頭架子上。"
s_ghoul_d	=[[食屍鬼是一種在墓園中活動，依靠吞噬屍體維持存在的不死生物。在傳說中，第一個食屍鬼乃是世界上頭一個嗜食人肉的人類所化，在他死時，這個惡人對活物血肉無止境的渴求將它帶回陽世；另一種說法是某個以自己親族的腐肉維生者，在他死於一種穢惡的疾病（並以食屍鬼的狀態復生）後成為了第一個食屍鬼——總而言之，對於這些不死的拾荒者迄今為止還缺乏一個確定的起源說。

食屍鬼在文明世界的邊緣地帶潛伏著（比如城市周邊的公墓和下水道中），在這些地方它們能輕鬆的獲取自己需要的食物。雖然食屍鬼更愛腐肉的味道（並經常將它們的受害者埋上一段時間調調味），不過在飢餓的狀態下它們也同樣很難抗拒殺戮和進食活物的衝動。多數生活在地表的食屍鬼處於原始的狀態，不過也有謠傳提到在深深的地下，一些食屍鬼的牧師統治著整個由食屍鬼組成的王國，它們供奉遠古的邪神和同樣飢渴的惡魔領主作為保護者。當然，更加“文明”的食屍鬼並不會考慮太多餐桌禮儀問題。事實上，想想由整個族群的食屍鬼圍坐一桌共饗人肉大宴和公墓裡的食屍鬼在棺材堆裡翻箱倒櫃，哪一個畫面要更加駭人一些？]]

s_lich		="巫妖"
s_lich_d	=[[巫妖是會施法的不死生物，通常是利用其法力以非自然的方式來延長其生命的法師或術士，有時也會是牧師或其他施法者。

巫妖是枯瘦且骷髏般的類人生物，它們凋萎的肌肉緊附在裸露的骨頭上。它們的眼睛很早以前就因腐朽而消失，但是在其空洞的眼眶中仍然閃爍著針尖般的緋紅光芒。

巫妖會說通用語及它生前所會的任何語言。

<b>巫妖人物</b>
變成巫妖的過程是無法形容的邪惡，並且只有自願的人物才能承受。巫妖保留其生前所有職業能力。

<b>巫妖的命匣</b>
變成巫妖必不可少的部分就是製造一個用來儲存生命能源的魔法命匣。每個巫妖都必須要製造它自己的命匣。

最常見的命匣外形是一個被封印的裝有撰刻著魔法文字的羊皮紙的超小型金屬盒。其他外形的命匣也存在，比如戒指，護符或類似的物品。

按照規則，消滅巫妖的唯一方式就是摧毀其命匣。除非其命匣被定位且被摧毀，巫妖會在它看上去被殺死後的1d10天內重生。]]

s_vampire	="吸血鬼"
s_vampire_d	=[[吸血鬼的外表如生前一般，只是容貌變得冷酷而野蠻，使它們看起來有狼一般的掠食者特徵。

和巫妖類似，他們愛慕虛榮而又頹廢，並可能以貴族自居。

雖然有著人類的特徵，吸血鬼仍然很容易辨認，它們不會投下影子，也不會在鏡子中留下映像。

吸血鬼會說他們生前所會的語言。]]
s_vampire_e	=[[<b>吸血鬼的弱點</b>
儘管威力非凡，吸血鬼也有相當多的弱點。

<b>驅除吸血鬼：</b>吸血鬼無法忍受強烈的大蒜氣味，所以不會接近有那種玩意兒的地方。類似的，會因鏡子或強大的神聖徽記而畏縮。這些東西不會傷害吸血鬼 — 他們只是不想靠近。一個畏縮的吸血鬼必須至少與拿著鏡子或聖徽的生物保持５尺距離並在該遭遇的剩餘時間中都不能接觸或近身攻擊拿者那類物品的生物。

吸血鬼也不能穿過流水，但是它可以乘船渡過或在棺材裡休息時被抬過去。

除非被主人邀請，否則他們也不能進入其他人的家或房子。他們可以進入那些明確說明對所有人開放的公共場所。

<b>殺死吸血鬼：</b>將吸血鬼的生命值降到０或更低可以使之無力化卻不能殺死它。但是，有些攻擊可以殺死吸血鬼。

被暴露在陽光下會使得吸血鬼迷亂：它將只能做一個移動動作或攻擊動作然後如果它無法逃脫，則在下一輪被完全摧毀。

類似的，將吸血鬼沒入流動的水中將每回合讓其損失１／３的生命值，直到第３回合它將被徹底摧毀。

將木樁插進吸血鬼的心臟也會瞬間殺死這個怪物。但除非身體被毀滅，它仍將在木樁被拔除時復活。

一個流行的方法是砍下它的腦袋然後將其嘴裡灌滿聖水（或其他類似的東西）。]]

s_vampire_spawn		="吸血衍體"
s_vampire_spawn_d	=[[吸血衍體是吸血鬼殺害凡人時產生的不死生物。如同它們的製造者一般，衍體也受縛於它們的棺材以及墓土。吸血衍體和生前看起來差不多，只是線條變得冷酷而顯得兇惡。

當遭遇凡人時，吸血衍體會使用它們非人的力量拳夯對手並拿對手往牆上或石頭上撞。它們也使用氣態形體和飛行能力尋找對手的弱點攻擊。

吸血衍體對所有可以驅除或殺死吸血鬼效果的攻擊同樣顯得十分脆弱。

吸血衍體說通用語。]]

-- 構裝體	Construct
s_golem		="魔像"
s_golem_d	=[[魔像是由魔法力量構建而成的自動裝置。創造魔像的過程通常要涉及到強大的魔法和元素力量的運用。

魔像的活化力量源於來自土元素位面的靈魂。創造魔像，簡而言之就是將一個不情願的靈魂植入到人造軀體內，並讓其按照創造者的意志行動。

魔像在戰鬥中相當頑強，而它們的身體也異乎尋常的強壯，而且對大多數魔法和超自然能力免疫。由於沒有心智，如果沒有創造者的指令他們什麼也不會幹。它們會明確的執行命令，但不懂得采取任何戰略或戰術。戰鬥中它們毫無感情，挑釁對於他們是無效的。]]
s_golem_e	=[[只要魔像在創造者周圍60尺範圍內，能夠看見他並聽到他的聲音，創造者就可以對它下達指令。如果未接到新的指令，魔像會盡力完成所接到的最後一項指令，但如果它遭到攻擊，仍會反擊。

當創造者不在的時候，他或她可以事先向魔像下達一些簡單的指令來控制它的行動。創造者可以命令魔像聽從其他人發出的指令（此人也可以將魔像的控制權交給他人，依次類推），無論如何創造者可以隨時重新控制他的造物，讓它只聽其一人的命令。]]

s_inevitable	="制裁者"
s_inevitable_d	=[[制裁者是將執行多元宇宙中的自然法規作為其唯一存在目的的構裝生物。

每種制裁者都被設計成能尋找並懲罰某種特定的罪行，捉拿違犯了基本法規的個人或團隊。當一個制裁者被製造出來時，它會接到它的第一次任務，然後去找到犯法者並給予其適當的懲罰。判決通常為死刑，但一些制裁者會堅決要求犯罪的團隊進行補償，並使用指使術或審判烙印或來確保其服從。

制裁者處於監視模式時在人群中格外醒目，但它們看起來對此毫不在意。它們形態各異，但所有的制裁者都是金銀製的發條生物，齒輪和活塞就是它們的肌肉。它們的眼睛閃爍著金色的光芒。

與絕大多數的構裝生物不同，制裁者擁有智力屬性值，並且可以思考、學習和記憶。

制裁者說深淵語，天界語，煉獄語和它們首個目標的母語。]]
s_inevitable_e	=[[從它起步開始，制裁者會完全專注於它的目標。無論線索多麼模糊，任務多麼無望，它都會堅持不懈。制裁者一心一意地追擊它們的獵物，它們奉命不干涉無辜者。它們獵物的同夥是可以攻擊的物件，然而，有些時候這會在它們的程式中產生矛盾。

除非威脅到其自身安全，制裁者會完完全全地專注於其目標，完全忽視其他戰鬥人員的存在。制裁者可能會攻擊任何阻礙它的人，但它若能再次著手於其目標的話則不會多做停留。制裁者十分重視自我保護；任何人若對制裁者展開它所認為能致命的攻擊的話，也會受到同樣致命的反擊。

制裁者很樂意犧牲自己以完成任務，但是它們不會自殺。面對失敗時，它們會撤退並尋找機會反擊。它們是堅決而耐心的對手。如果有助於完成任務它們會與其他人聯盟，但這聯盟不會維持很久。]]

-- 其他		Others
s_lycanthrope	="獸化人"
s_lycanthrope_d	=[[獸化人是能夠變化成動物的類人生物或巨人類生物。

在其天生形態下，獸化人看起來就和它的同類生物一樣，但是天生獸化人和那些被傳染了很久的獸化人會擁有其動物形態的特徵。

在動物形態下，獸化人像是更加強悍的普通動物，但如果靠近觀察的話，可以看到它的眼睛（在黑暗中會發紅光）中閃耀著不尋常的智慧的火花。

獸化症可以像疾病一樣傳播。有時普通的類人生物或巨人類生物在被獸化人攻擊而受傷之後會感染獸化症。這樣的生物被稱為受傳染的獸化人。其他生下來就是獸化人的獸化人，被稱為天生獸化人。

常見的獸化人包括狼人，鼠人，熊人，虎人和野豬人等。]]
s_lycanthrope_e	=[[處於類人（或巨人）形態下的獸化人會使用其同類生物所使用的任何戰術和武器，然而會更具攻擊性。獸化人擁有其動物形態的官能，包括靈敏嗅覺和昏暗視覺，而且還可以深刻地理解它所能變化成的那類動物（並擁有與之交流的能力）。受傳染的獸化人如果在戰鬥中受傷就可能被憤怒所壓倒，使其非自發地變成動物形態。

動物形態下的獸化人就如其所變成的動物一樣戰鬥，但它的齧咬攻擊卻可傳播獸化症。它非常狡詐而且極為強壯，並且擁有隻能被鍍銀武器所擊破的傷害減免能力。

天生獸化人（或意識到自己已被傳染的受傳染獸化人）可以變成混合了其類人和動物形態的混種形態。混種形態下的獸化人有手且可使用武器，但也可以使用其利齒和爪子進行攻擊。混種形態下的獸化人可以透過其齧咬攻擊傳播獸化症，而且擁有與其動物形態相同的傷害減免能力。]]


s_u_tps			= "生物型別"
s_u_tps_d		= [[每種生物都從屬某一物種（型別），其大致決定了生物的能力。某些生物還會從屬於一個或多個亞種（子型別）。

除非受到特殊能力的影響，否則生物無法違背其物種的特性 — 而新的生物模板可能會徹底改變生物原有種族特性。


每種生物型別的描述都以相同的格式組織，如下所述。


<b>生命骰（簡稱HD）</b>
有兩種含義，一是決定生物生命值的骰面。雖然還有體質值等因素，但生命骰可作為一項重要參考來衡量生物的生命值。

另一含義是衡量生物強度的數值，類似於玩家角色等級，但無職業（或某些複雜情況）的生物需用生命骰數來代替此強度數值。


<b>基本攻擊加值（簡稱BAB）</b>
基於生物型別，生物的BAB等於其HD總數（類似於戰士），或3/4（類似於牧師），或1/2（類似於法師）。


<b>強項豁免</b>
不同的生物型別有不同的強項豁免：某項或多項豁免高於其他豁免。不過也有少數生物型別各項豁免都很強。


<b>每HD技能點數</b>
生物每獲得一個HD，獲得的技能點數為x + 智力調整值，最少為1。首個HD的技能點數為此點數的4倍。

但前提是此生物有智力值，否則它的每HD技能點數為0。有些生物型別沒有心智，也無法獲得技能點數和專長。


<c=twa>（完整起見，以下給出規則中所有的生物型別以供參考，包括那些尚未出現在遊戲中的。）</c>]]


s_u_sub_tps		= "生物亞種"
s_u_sub_tps_d	= [[有些生物有一個或多個亞種。亞種能為生物增加額外的能力和特性。

<c=twa>（完整起見，以下給出規則中所有的生物亞種以供參考，包括那些尚未出現在遊戲中的。）</c>]]


s_ut_hum_hd		= "類人生物的生命骰"
s_ut_hum_hd_d	= [[只有一個生命骰的類人生物，用PC或NPC職業的職業特性來代替他的類人生物生命骰中的特性。

此類類人生物體現為1級武者，表明他們具備一般的戰鬥能力和較弱的豁免。

只有具有不止一個生命骰的類人生物才使用類人生物的特徵。]]


-- z_u_tp
u_tps_text={

[uc_hum]={n="類人生物"	,d=[[類人生物通常具有雙臂、雙腿及一個腦袋，或者有類似於人類的軀幹、四肢和頭部。

類人生物只有很少的超自然能力或特異能力，或者完全沒有，但他們大多數可以用語言交談，並通常有較為發達的社會結構。

他們的體型通常為中或小體型。每個類人生物都屬於一個亞種。

<b>特徵：</b>
- 生命骰：d8；或由職業等級決定。
- 基本攻擊加值：3/4 HD總數。
- 強項豁免：反射（通常為反射，但不同的類人生物具有不同的強項豁免）。
- 每HD技能點數：2 + 智力調整值；或由職業等級決定。

<b>特性：</b>
- 擅長所有簡易武器；或由職業等級決定。
- 如穿戴盔甲，則擅長此盔甲同類或更輕的盔甲，以及盾牌；或由職業等級決定。
- 需要進食、睡眠和呼吸。]]},


[uc_gnt]={n="巨人"	,d=[[巨人是類人形狀的生物，力量巨大，通常至少是大體型。

所有巨人都會說巨人語。智力值10或以上的巨人還會說通用語。

<b>特徵：</b>
- 生命骰：d8。
- 基本攻擊加值：3/4 HD總數。
- 強項豁免：強韌。
- 每HD技能點數：2 + 智力調整值。

<b>特性：</b>
- 昏暗視覺。
- 擅長所有簡易和軍用武器，以及任何天生武器。
- 如有穿戴盔甲，則擅長此盔甲同類或更輕的盔甲，以及盾牌。
- 需要進食、睡眠和呼吸。]]},


[uc_fey]={n="精類"	,d=[[精類是具有超自然能力的生物，他們和自然界或一些其他的力量或地點聯絡在一起。精類通常具有人類的外形。

<b>特徵：</b>
- 生命骰：d6。
- 基本攻擊加值：1/2 HD總數。
- 強項豁免：反射和意志。
- 每HD技能點數：6 + 智力調整值。

<b>特性：</b>
- 昏暗視覺。
- 擅長所有簡易武器和所使用武器。
- 如有穿戴盔甲，則擅長此盔甲同類或更輕的盔甲，以及盾牌。
- 需要進食、睡眠和呼吸。]]},


[uc_hmm]={n="人形怪物"	,d=[[人形怪物與類人生物相似，但同時具有怪物或動物的特徵。他們通常也具有魔法能力。

<b>特徵：</b>
- 生命骰：d8。
- 基本攻擊加值：HD總數。
- 強項豁免：反射和意志。
- 每HD技能點數：2 + 智力調整值。

<b>特性：</b>
- 黑暗視覺60尺。
- 擅長所有簡易武器和所使用武器。
- 如有穿戴盔甲，則擅長此盔甲同類或更輕的盔甲，以及盾牌。
- 需要進食、睡眠和呼吸。]]},


[uc_out]={n="異界生物"	,d=[[異界生物至少有一部分本質（但不一定是物質）是主物質位面以外的某個位面的產物。

一些生物可能原本屬於其它型別，當它們達到更高（或更低）層次的精神狀態時變成了異界生物。

典型的異界生物包括天使，魔鬼和巨靈等。而神魔裔則是較典型的本地異界生物。

<b>特徵：</b>
- 生命骰：d8。
- 基本攻擊加值：HD總數。
- 強項豁免：強韌、反射和意志。
- 每HD技能點數：8 + 智力調整值。

<b>特性：</b>
- 黑暗視覺60尺。
- 與大多數活物不同，異界生物不具二元性 - 它的靈魂和身體合二為一。當一個異界生物死亡時，不會有靈魂得到釋放。將靈魂返還身體的普通法術對非本地異界生物無效。它需要更強力的法術效果來讓它恢復生命。
- 擅長所有簡易和軍用武器，以及所使用武器。
- 如有穿戴盔甲，則擅長此盔甲同類或更輕的盔甲，以及盾牌。
- 需要呼吸，但不需要進食或睡眠（雖然如果想要的話它們也可以這麼做）。本地異界生物需要進食、睡眠和呼吸。]]},


[uc_elm]={n="元素"	,d=[[元素是由四種基本元素：風、土、火、水之一所形成的生物。元素生物就是形成萬物的元素的化身。

<b>特徵：</b>
- 生命骰：d8。
- 基本攻擊加值：3/4 HD總數。
- 強項豁免：強韌（土、水）或反射（風、火）。
- 每HD技能點數：2 + 智力調整值。

<b>特性：</b>
- 黑暗視覺60尺。
- 對毒素、魔法睡眠、麻痺和震懾免疫。
- 不受重擊或夾擊。
- 與大多數活物不同，元素不具二元性 - 它的靈魂和身體合二為一。當一個元素死亡時，不會有靈魂得到釋放。將靈魂返還身體的普通法術對它無效。它需要更強力的法術效果來讓它恢復生命。
- 僅擅長它的天生武器。除非通常處於類人形態，則擅長所有簡易武器和所使用武器。
- 如有穿戴盔甲，則擅長此盔甲同類或更輕的盔甲，以及盾牌。
- 不需要進食、睡眠或呼吸。]]},


[uc_abr]={n="異怪"	,d=[[異怪通常具有奇異的生理結構，千奇百怪的特殊能力，怪異的思維方式，或者這三者的任意組合。

<b>特徵：</b>
- 生命骰：d8。
- 基本攻擊加值：3/4 HD總數。
- 強項豁免：意志。
- 每HD技能點數：2 + 智力調整值。

<b>特性：</b>
- 黑暗視覺60尺。
- 擅長它的天生武器。若通常形態類人，則擅長所有簡易武器和所使用武器。
- 如有穿戴盔甲，則擅長此盔甲同類或更輕的盔甲，以及盾牌。
- 需要進食、睡眠和呼吸。]]},


[uc_dgn]={n="龍"	,d=[[龍是一種類爬蟲生物，他們通常有翅膀、具有魔法和非凡的能力。

<b>特徵：</b>
- 生命骰：d12。
- 基本攻擊加值：HD總數。
- 強項豁免：強韌、反射和意志。
- 每HD技能點數：6 + 智力調整值。

<b>特性：</b>
- 黑暗視覺60尺和昏暗視覺。
- 免疫魔法睡眠和麻痺。
- 僅擅長它的天生武器。若正處於或可變成類人形態，則擅長所有簡易武器和所使用武器。
- 不擅長任何盔甲。
- 需要進食、睡眠和呼吸。]]},


[uc_ani]={n="動物"	,d=[[動物是非人類的活體生物，通常為不具有魔法屬性也不具有語言和文化天賦的脊椎動物。

這些生物通常依其本能而行動，由食物、繁殖之類的最基本需求所驅動。除非本身或其幼崽受到威脅，大多數的動物，即使是食肉動物，也不會主動攻擊。

儘管通過馴養動物技能可以馴服動物或教會它做一些把戲，但是動物沒有進行詳細推理的能力。

一些食草動物通常不會使用其天生武器進行攻擊。同樣的，它們的天生武器被視為次要攻擊。

<b>特徵：</b>
- 生命骰：d8。
- 基本攻擊加值：3/4 HD總數。
- 強項豁免：強韌和反射（兇暴動物3項豁免均為強項；個別動物有不同的強項）。
- 每HD技能點數：2 + 智力調整值。

<b>特性：</b>
- 智力值為1或2（不存在智力值高於2的動物）。
- 昏暗視覺。
- 陣營：總是中立。動物不受人類道德的支配。
- 寶藏：通常不擁有寶藏，若有也是被其殺死的生物所留下的。
- 僅擅長它的天生武器。非戰鬥草食動物使用其天生武器視為次要攻擊。這樣的攻擊在攻擊判定上有-5減值，並且在傷害調整值上只能獲得1/2它的力量調整值。
- 除非經過戰鬥訓練，否則無法擅長任何盔甲。
- 需要進食、睡眠和呼吸。]]},-- 寶藏：無。動物不會擁有寶物。	Treasure: None. Animals never possess treasure.


[uc_anm]={n="魔法獸"	,d=[[魔法獸和動物相似，但是可以具有高於2的智力值。魔法獸通常具有超自然或特異能力，但有時候僅僅是在外表或習性上奇特而已。

<b>特徵：</b>
- 生命骰：d10。
- 基本攻擊加值：HD總數。
- 強項豁免：強韌和反射。
- 每HD技能點數：2 + 智力調整值。

<b>特性：</b>
- 黑暗視覺60尺和昏暗視覺。
- 僅擅長它的天生武器。
- 不擅長任何盔甲。
- 需要進食、睡眠和呼吸。]]},


[uc_bug]={n="蟲類"	,d=[[蟲類包括昆蟲、蜘蛛、其他節肢動物、蠕蟲以及類似無脊椎動物。

此類生物依本能行動，由食物及繁殖之類的基本需求所驅動。蟲類生物通常只有在飢餓或受到威脅時才會攻擊。

<b>特徵：</b>
- 生命骰：d8。
- 基本攻擊加值：3/4 HD總數。
- 強項豁免：強韌。
- 每HD技能點數：2 + 智力調整值。大多數蟲類沒有心智，也無法獲得技能點數和專長。

<b>特性：</b>
- 無心智：沒有智力值，免疫所有影響心靈的效果。
- 黑暗視覺60尺。
- 陣營：總是中立。蟲類不受人類道德的支配。
- 寶藏：通常不擁有寶藏，若有也是被其殺死的生物所留下的。
- 僅擅長它的天生武器。
- 不擅長任何盔甲。
- 需要進食、睡眠和呼吸。]]},


[uc_plt]={n="植物"	,d=[[這一型別由植物類的生物組成。注意，通常的植物，比如在田野或者果園中種植的植物，缺少感知和魅力屬性，不是生物而是物體，即使它們是活著的。

<b>特徵：</b>
- 生命骰：d8。
- 基本攻擊加值：3/4 HD總數。
- 強項豁免：強韌。
- 每HD技能點數：2 + 智力調整值。某些植物沒有心智，也無法獲得技能點數和專長。

<b>特性：</b>
- 昏暗視覺。
- 免疫所有影響心靈的效果。
- 免疫毒素、睡眠、麻痺、變形和震懾。
- 不受重擊。
- 僅擅長它的天生武器。
- 不擅長任何盔甲。
- 需要進食和呼吸，但不需要睡眠。]]},


[uc_ooz]={n="泥形怪物"	,d=[[泥形怪物是無具體形狀或易變形的生物，通常沒有心智，活著就是為了吃。

它們棲息於各地的地下區域，侵蝕而成的洞穴，廢墟和地下城中，尋找有機物 — 無論死活。

泥形怪物會攻擊它們遇到的任何生物。它們會用偽足猛擊或乾脆用身體吞噬對手，身體分泌的酸液能幫助它們捕捉或消化獵物。

<b>特徵：</b>
- 生命骰：d10。
- 基本攻擊加值：3/4 HD總數。
- 強項豁免：無。
- 每HD技能點數：2 + 智力調整值。大多數泥形怪物沒有心智，也無法獲得技能點數和專長。

<b>特性：</b>
- 無心智：沒有智力值，免疫所有影響心靈的效果。
- 目盲（但具有盲視特性），免疫凝視攻擊、視覺效果、幻象和其他依賴視覺的攻擊形式。
- 盲視（特異）：泥形怪全身都遍佈感覺器官，它們會自動察覺周圍60尺內的氣味和振動。
- 免疫毒素、睡眠、麻痺、變形和震懾。
- 不受重擊或夾擊。
- 某些泥形怪物能夠對物體造成強酸傷害，每接觸一整輪造成的傷害 = 10 + 1/2泥形怪物的HD + 它的體質調整值。
- 僅擅長它的天生武器。
- 不擅長任何盔甲。
- 需要進食和呼吸，但不需要睡眠。]]},


[uc_und]={n="不死生物"	,d=[[它們曾經是生物，但在死去以後被精神或超自然力量活化了，成為了不死生物。

<b>特徵：</b>
- 生命骰：d12。
- 基本攻擊加值：1/2 HD總數。
- 強項豁免：意志。
- 每HD技能點數：4 + 智力調整值。很多不死生物沒有心智，也無法獲得技能點數和專長。

<b>特性：</b>
- 無體質值。
- 黑暗視覺60尺。
- 免疫所有影響心靈的效果。
- 免疫毒素、睡眠、麻痺、震懾、疾病和死亡效果。
- 免疫任何需要強韌豁免的效果（除非此效果同樣對物體有效，或無害）。
- 不受重擊、非致命傷害、屬性吸取、能量吸取的影響。免疫對身體屬性（力量、敏捷、體質）造成的傷害，免疫疲勞和力竭的效果。
- 若無智力值則無法自己醫治傷害，但可以被治療。負能量可以治療不死生物。快速痊癒特性不管是否有智力值都一樣運作。
- 不受死者復生等法術或類法術能力影響。
- 專注檢定時使用魅力調整值。
- 擅長它的天生武器，所有簡易武器和所使用武器。
- 如有穿戴盔甲，則擅長此盔甲同類或更輕的盔甲，以及盾牌。
- 不需要進食、睡眠或呼吸。]]},-- 不會因巨創而死亡。在生命值減為0或更低的時候便立即被摧毀。	復活術和完全復活術能影響不死生物。它們會將不死生物變回它們在變為不死生物之前的活物。	Not at risk of death from massive damage, but when reduced to 0 hit points or less, it is immediately destroyed.		Resurrection and true resurrection can affect undead. These spells turn undead creatures back into the living creatures they were before becoming undead.


[uc_cst]={n="構裝體"	,d=[[構裝體是活化的物體，或人工製造的生物。

<b>特徵：</b>
- 生命骰：d10。
- 基本攻擊加值：3/4 HD總數。
- 強項豁免：無。
- 每HD技能點數：2 + 智力調整值。大多數構裝體沒有心智，也無法獲得技能點數和專長。

<b>特性：</b>
- 無體質值。
- 黑暗視覺60尺和昏暗視覺。
- 免疫所有影響心靈的效果。
- 免疫毒素、睡眠、麻痺、震懾、疾病、死亡和死靈系效果。
- 免疫任何需要強韌豁免的效果（除非此效果同樣對物體有效，或無害）。
- 不受重擊、非致命傷害、屬性傷害、屬性吸取、疲勞、力竭和能量吸取影響。
- 無法自行回覆傷害，但常常可以在某些特定效果下得到修復。具有快速痊癒特性的構裝體仍可同樣的自療。
- 因為它不是活物，所以無法被複生或復活。
- 因為它的身體是一塊無生命的物質，構裝體很難被摧毀。根據體型它獲得額外生命值，如下表：
	構裝體大小	生命值獎勵
	超微型		-
	微型		-
	超小型		-
	小型		10
	中型		20
	大型		30
	超大型		40
	巨型		60
	超巨型		80
- 僅擅長它的天生武器。若通常形態類人，則擅長所使用武器。
- 不擅長任何盔甲。
- 不需要進食、睡眠或呼吸。]]},-- ，或通過使用製造構裝體專長修復	不會因巨創而死亡。在生命值減為0或更低的時候便被摧毀。	or through the use of the Craft Construct feat	— Not at risk of death from massive damage. Immediately destroyed when reduced to 0 hit points or less.
}

-- z_u_sub_tp
u_sub_tps_text={
[ust_hum]={n="人類"			,d="此亞種包括人類，或和人類有血緣關係的生物。"},
[ust_elf]={n="精靈"			,d="此亞種包括精靈，或和精靈有血緣關係的生物，如半精靈。\n\n精靈亞種生物有昏暗視覺。"},
[ust_dwf]={n="矮人"			,d="此亞種包括矮人，或和矮人有血緣關係的生物。\n\n矮人亞種生物有60尺黑暗視覺。"},
[ust_gnm]={n="侏儒"			,d="此亞種包括侏儒，或和侏儒有血緣關係的生物。\n\n侏儒亞種生物有昏暗視覺。"},
[ust_hfl]={n="半身人"		,d="此亞種包括半身人，或和半身人有血緣關係的生物。"},
[ust_orc]={n="獸人"			,d="此亞種包括獸人，或和獸人有血緣關係的生物，如半獸人。\n\n獸人亞種生物有60尺黑暗視覺和強光敏感（半獸人無強光敏感）。"},
[ust_gob]={n=s_goblinoid	,d=s_goblinoid_d},
[ust_gnl]={n=s_gnoll		,d=s_gnoll_d	},
[ust_cat]={n=s_catfolk		,d=s_catfolk_d	},
[ust_rep]={n="爬蟲"			,d="這類生物具有鱗殼並通常是冷血動物。\n\n爬蟲亞種僅用來描述一些類人生物種族，而不是那些真正的爬行動物或怪物。"},
[ust_aqu]={n="水棲"			,d="這類生物總是有游泳速度，因此它們可以在水中移動而不需要作游泳檢定。\n\n水棲生物可以在水下呼吸。除非它具有兩棲特性，否則它不能在水面以上呼吸。"},
[ust_aug]={n="增強"			,d="生物的原始種類發生某種變化時它將獲得此亞種。\n\n一些生物（那些具有繼承模板的生物）天生屬於此亞種；而其它則是在它們獲得某一模板的時候成為此亞種。\n\n增強亞種總是和生物的原始種類成對出現。具有增強亞種的生物往往擁有當前種類的特性，卻保留原始種類的特徵。"},
[ust_fir]={n="火系"			,d="火系亞種的生物免疫火焰，但懼怕寒冷。\n\n寒冷會對它們造成比正常多一半的傷害，無論是否有豁免和是否通過了豁免。"},
[ust_col]={n="寒系"			,d="寒系亞種的生物免疫寒冷，但懼怕火焰。\n\n火焰會對它們造成比正常多一半的傷害，無論是否有豁免和是否通過了豁免。"},
[ust_air]={n="風系"			,d="此亞種包括和風元素位面相關的元素和異界生物。\n\n風系生物總是具有飛行速度且常常有完美的飛行機動性。"},
[ust_wtr]={n="水系"			,d="此亞種包括和水元素位面相關的元素和異界生物。\n\n水系生物總是具有游泳速度，在水中移動時不需要進行遊泳檢定。\n\n水系生物可以在水下呼吸，通常也可以呼吸空氣。"},
[ust_eth]={n="土系"			,d="此亞種包括和土元素位面相關的元素和異界生物。\n\n土系生物通常具有掘穴速度，且大多數都可以挖掘開堅硬的石頭。"},
[ust_goo]={n="善良"			,d="此亞種通常只適用於居住在善良陣營外位面上的異界生物。\n\n絕大多數此亞種生物也具有善良陣營；但如果他們的陣營發生變化，他們仍然維持此亞種不變。\n\n在計算依賴於陣營的效果影響時，無論本身陣營如何善良亞種的生物都被視為善良陣營。它也會同樣因為它的自身實際陣營而受到影響。\n\n善良亞種的生物在對抗傷害減免時，它的天生武器和任何持有的武器都視作具有善良陣營。"},
[ust_evl]={n="邪惡"			,d="此亞種通常只適用於居住在邪惡陣營外位面上的異界生物。\n\n絕大多數此亞種生物也具有邪惡陣營；但如果他們的陣營發生變化，他們仍然維持此亞種不變。\n\n在計算依賴於陣營的效果影響時，無論本身陣營如何邪惡亞種的生物都被視為邪惡陣營。它也會同樣因為它的自身實際陣營而受到影響。\n\n邪惡亞種的生物在對抗傷害減免時，它的天生武器和任何持有的武器都視作具有邪惡陣營。\n\n邪惡的異界生物也常被稱作妖魔。"},
[ust_law]={n="守序"			,d="此亞種通常只適用於居住在守序陣營外位面上的異界生物。\n\n絕大多數此亞種生物也具有守序陣營；但如果他們的陣營發生變化，他們仍然維持此亞種不變。\n\n在計算依賴於陣營的效果影響時，無論本身陣營如何守序亞種的生物都被視為守序陣營。它也會同樣因為它的自身實際陣營而受到影響。\n\n守序亞種的生物在對抗傷害減免時，它的天生武器和任何持有的武器都視作具有守序陣營。"},
[ust_cho]={n="混亂"			,d="此亞種通常只適用於居住在混亂陣營外位面上的異界生物。\n\n絕大多數此亞種生物也具有混亂陣營；但如果他們的陣營發生變化，他們仍然維持此亞種不變。\n\n在計算依賴於陣營的效果影響時，無論本身陣營如何混亂亞種的生物都被視為混亂陣營。它也會同樣因為它的自身實際陣營而受到影響。\n\n混亂亞種的生物在對抗傷害減免時，它的天生武器和任何持有的武器都視作具有混亂陣營。"},
[ust_nat]={n="本地"			,d="此亞種只針對異界生物。這些生物存在凡人祖先，或與主物質位面有牢固的聯絡，並且可以象其他生物一樣被複生、轉生或復活。\n\n屬於此亞種的生物是主物質位面的本地居民（即這個亞種名稱的來由）。\n\n不象真正的異界生物，本地異界生物需要進食和睡眠。"},
[ust_ext]={n="跨位面"		,d="此亞種指那些不在它原本所屬位面的生物。一個在位面間旅行的生物在轉移位面時可能獲得或失去此亞種。\n\n相關描述中假定生物之間的遭遇發生在主物質位面，於是那些原本不屬於主位面的生物都是跨位面亞種（但當它在其原始位面的時候便不是了）。\n\n跨位面生物描述中都註明了原本所屬的位面。未標明跨位面的生物都屬於主物質位面，當他們離開主物質位面的時候將獲得此亞種。\n\n正處於過渡位面，如星界、靈界位面和陰影位面的生物不會獲得跨位面亞種。"},


[ust_ang]={n=s_angel		,d=s_angel_d.."\n\n"..[[
<b>特性：</b>
- 黑暗視覺60尺和昏暗視覺。
- 免疫強酸、寒冷和石化。
- 電擊抗力10，火焰抗力10。
- 毒素豁免+4種族加值。
- 防護靈氣（超自然能力）：天使周圍20尺以內的任何人對抗邪惡生物作出的攻擊或產生的效果時，防禦等級+4偏斜加值，豁免+4抗力加值。此外，它的作用還相當於反邪惡法陣和次級防護法球的效果，半徑均為20尺（施法者等級等同於天使的HD）。此靈氣可被驅散，但天使可以在下一回合以一個自由動作再次創造它。（法陣的防禦優勢未計入天使的資料。）
- 巧言（超自然能力）：所有天使都能夠和任何有語言的生物交談，如同巧言術（施法者等級等同於天使的HD）。此能力始終處於啟動狀態。]]},


[ust_arc]={n=s_archon		,d=s_archon_d.."\n\n"..[[
<b>特性：</b>
- 黑暗視覺60尺和昏暗視覺。
- 免疫電擊和石化。
- 毒素豁免+4種族加值。
- 威嚇靈氣（超自然能力）：一股正義的靈氣環繞著戰鬥中或憤怒的神使。神使身旁20尺半徑內的任何敵對生物必須成功地通過一次意志豁免來抵抗它的效果。豁免DC基於魅力，幷包含+2種族加值，具體數值因神使型別的不同而變化。豁免失敗者在攻擊、防禦等級和豁免上受到-2減值，持續24小時或直到他們成功擊中了產生此靈氣的神使為止。已成功抵抗或破除此效果的生物在24小時內不會再被同一神使的靈氣影響。
- 反邪惡法陣（超自然能力）：反邪惡法陣效果始終環繞著神使（施法者等級等同於神使的HD）。（法陣的防禦優勢未計入神使的資料。）
- 傳送（超自然能力）：神使可以任意使用高等傳送術，相當於同名法術（施法者等級14），但她只能傳送自己，外加不超過50磅的物體。
- 巧言（超自然能力）：所有神使都能夠和任何有語言的生物交談，如同巧言術（施法者等級14）。此能力始終處於啟動狀態。]]},


[ust_shp]={n="變形生物"	,d=[[變形生物具有某種超自然能力可以呈現出一種或多種變化形態。許多魔法效果都可以做到某種外形上的改變，並非所有能改變外形的生物都具有變形生物亞種。

<b>特性：</b>
- 擅長它的天生武器、簡易武器和所使用武器。
- 如有穿戴盔甲，則擅長此盔甲同類或更輕的盔甲，以及盾牌。]]},


[ust_inc]={n="虛體"	,d=[[虛體生物不具備肉體。只有其他虛體生物、魔法武器或使用魔法武器攻擊的生物、法術、類法術能力或超自然能力能對它造成傷害。它免疫所有非魔法攻擊。即便被法術或魔法武器擊中，它仍有50%機會忽略來自於實體的傷害（除了正能量、負能量、力場作用例如魔法飛彈、或由幽冥武器發起的攻擊）。雖然不屬於魔法攻擊，但聖水可以影響虛體不死生物，儘管聖水的作用仍有50%的機會無法影響到虛體。

虛體生物沒有天生防禦加值，但具有等同於它魅力加值的偏斜加值（至少為+1，即使生物的魅力值沒有提供加值）。

虛體生物可以隨意進入或者穿過固體物質，但必須要和物體的外表面相接，因此無法完全穿過一個比它自身空間更大的物體。這時它可以感知它所在位置相鄰方格中生物或物體的存在，但敵人對於在物體中的虛體仍然存在完全隱蔽（50%失手機率）。為了從物體中看得更遠並進行正常攻擊，虛體必須從物體中浮現出來。在物體中的虛體具有全掩蔽，但當它攻擊物體外的生物時它僅存在掩蔽，因此外面的生物可以用準備動作在它展開攻擊時進行攻擊。虛體生物無法穿過力場效果。

虛體生物的攻擊可以穿透（忽略）天生防禦、盔甲和盾牌，但偏斜加值和力場效果（比如法師護甲）對它有效。虛體生物可以象在空氣中那樣在水中穿過或進行動作。虛體生物不會墜落或受到墜落傷害。虛體不可以展開絆摔或擒抱攻擊，也無法被絆摔或被擒抱。實際上，它們無法作出任何有關實質形體的動作，來針對一個對手或其裝備進行挪動或操作，反之這類動作也對它們無效。虛體生物沒有體重，也不會觸發那些由重量觸發的陷阱。

虛體生物移動時很安靜，只要它不想被聽到，通過聆聽檢定是無法覺察的。它沒有力量屬性，因此它的近戰和遠端攻擊都使用它的敏捷調整值。視力以外的手段，比如靈敏嗅覺或盲視，在針對虛體時或者無效，或者僅部分有效。虛體生物對方向有著天生的感知，即使它們看不見也可以全速移動。]]},


[ust_swm]={n="叢集"	,d=[[叢集由一大群密集的超微型、微型或超小型生物組成，它們在行動方式上看作是一個生物。這些生物在分成小群時沒有什麼威脅，但聚到足夠的數量之後會變得相當危險。

許多不同的生物都可以組成叢集：蝙蝠叢集、蜈蚣叢集、黃蜂叢集、蝗蟲叢集、老鼠叢集和蜘蛛叢集。叢集的生物類別和組成生物的天然類別一樣（大多數是動物或蟲類），但所有叢集都有叢集亞種。

除了如下的說明之外，一個叢集具有組成它的個體種類的性質。叢集有單一的生命骰和生命值，單一的先攻調整值，單一的移動速度，以及單一的防禦等級。叢集在進行豁免檢定時亦和單個生物一樣。

一個叢集佔據邊長10尺的正方形（如果由不會飛的生物組成）或立方體（由飛行生物組成），但和組成它的生物一樣觸及為0尺。

在攻擊時，它會移進對手所佔據的空間，這可能引發藉機攻擊。

由於它會附著在獵物身上，因此可以和任意大小的生物一起佔據共同的空間，但在10英尺空間內依然是單一的生物。

叢集無法進行藉機攻擊，但能引發藉機攻擊。

叢集可以不受阻礙的穿越敵人佔據的方格，反之也如此，但叢集這麼做會引發藉機攻擊。

和其他佔據10英尺空間的生物不同，叢集的形狀可以改變。它可以佔據任意四個鄰接的方格，並且任何空間只要能容納一隻組成叢集的生物，這個叢集就能夠穿越它。如果一個裂縫或者洞口足夠組成叢集的生物通過，那麼叢集也可以通過。

一群超小型生物包含300只不會飛的生物或1,000只飛行生物。
一群微型生物包含1,500只不會飛的生物或5,000只飛行生物。
而一群超微型生物包含10,000只生物，無論會飛與否。

在不會飛的叢集中，生物通常是緊緊地堆疊在一起，在移動和進攻時翻越其它的個體一起向獵物湧去，所以它們具有比10尺見方通常能容納的多得多的數量。更大的叢集可由多個單個叢集的總和來體現。大型叢集所佔據的區域形狀可以隨意改變，但是叢集通常會保持所佔據方格都是相鄰的，即巨型的聚落可被分為互相貼近的幾個叢集。

<b>特性：</b>
由微型和超微型生物組成的叢集免疫所有武器傷害。
由超小型生物組成的叢集對於揮砍或穿刺武器只受一半傷害。
叢集沒有明顯的前胸後背也不存在明確的生理結構，因此它不受重擊和夾擊。
叢集不會被絆摔、擒抱或衝撞，也無法擒抱對手。
免疫針對具體數目生物的法術或效果（包括單目標法術比如解離術），但如果叢集有智力值和群體意識，則影響心靈的效果例外。
將一個叢集的生命值減到0或更低可以將它打散，但直到該數目以前的傷害都無法降低它攻擊和抵禦攻擊的能力。叢集從不會因受傷而失去戰鬥力或者處於瀕死狀態。
影響區域的法術或效果可對叢集額外造成一半的傷害，比如潑濺武器和許多塑能系法術。
由微型或超微型生物組成的叢集易受強風的影響。在決定風對於叢集的影響時，叢集看作具有和組成它的生物相同的體型。因為受到非致命傷害而昏迷的叢集會亂作一團並分散開，只有在它的生命值超過它所受非致命傷害時才會重新組織起來。

<b>叢集的弱點：</b>用物理攻擊對戰叢集極其困難。但叢集有一些特殊的弱點。
揮舞點燃的火把作為臨時武器每擊會造成1d3的火焰傷害。
擁有熾焰或凍寒等特性的武器每擊會對其造成完整的能量傷害，儘管武器的正常傷害無法影響叢集。
點燃的提燈可作為投擲武器，對其炸開的鄰接方格中所有生物造成1d4火焰傷害。


<b>叢集攻擊：</b>具有叢集的生物不會展開通常的近身攻擊。取而代之，它們不需要進行攻擊檢定即可對它們移動結束時所佔據格子中的任何生物自動造成傷害。叢集攻擊沒有攻擊加值，也不受隱蔽或掩蔽所帶來的失手機率的影響。

一個叢集造成的傷害基於它的HD，如下：
叢集HD		叢集基本傷害
1-5		1d6
6-10		2d6
11-15		3d6
16-20		4d6
21+		5d6

除非特別說明，叢集攻擊是沒有魔法性質的。假如一個生物具有足夠將叢集攻擊傷害抵消到0的傷害減免、是虛體或是具有一些其他特性，則通常可免疫（或至少可抵消一些）來自一個叢集的攻擊傷害。一些叢集在造成正常傷害的同時還會造成附加的酸、毒、吸血或者其他特殊攻擊。


叢集並不威脅同一方格中的生物，也無法用它的叢集攻擊作出藉機攻擊。但是，它們能擾亂他們所佔據方格內的對手的心神，見下面描述。

<b>擾亂心神（特異能力）：</b>任何易受叢集傷害的活物，在它回合開始時若和一個叢集在同一個方格內，會反胃一回合；通過強韌豁免（DC = 10 + 1/2叢集HD + 它的體質調整值）則不受影響。在叢集佔據範圍中施法或維持專注需要進行專注檢定（DC = 20 + 法術等級）。這種情況下，使用需要耐心和集中精神的技能也需要進行DC20的專注檢定。]]},
}